(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vitcop-vlm-prefill"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-1\">一 · 一次 TTFT 雪崩：预填被视觉 token 淹没</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-2\">二 · 算法边界：一次性筛选，不碰解码与拓扑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-3\">三 · 收益结构与代价结构必须成对核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-4\">四 · 适用边界的判定方法：按任务而非按模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-5\">五 · 为什么训练无关是它最重要的稳定性属性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-6\">六 · 失效边界：指令模糊与细粒度任务上的误删代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-7\">七 · 图像入口：patch 切分与 ViT 编码的代价锚点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-8\">八 · 跨模态打分：文本嵌入与视觉 token 的余弦对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-9\">九 · 保留与合并：top-k 选择加空间邻接摘要</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-10\">十 · 拼接与 LLM 预填：压缩后 token 序列的算力账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-11\">十一 · KV cache 分配与解码复用：显存账与上下文风险</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-12\">十二 · 步骤间的耦合与流水线排布</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-13\">十三 · 筛选发生在哪一段：一次性插件的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-14\">十四 · 预填时延公式的四项分解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-15\">十五 · 相关性打分的可实现形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-16\">十六 · 合并算子与空间邻接的代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-17\">十七 · 预算反解与批内异构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-18\">十八 · 数值精度与硬件落点的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-19\">十九 · 从公式到验收口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-20\">二十 · 一次性筛选的边界：打分退化、合并失真与保留率失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-21\">二十一 · 请求形态：指令明确度决定保留率能否落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-22\">二十二 · 长度分布：视觉 token 基数与文本 token 比例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-23\">二十三 · 并发与批大小：保留率如何改变批的构成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-24\">二十四 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-25\">二十五 · 配方落地：把保留率做成按桶可调的运行时参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-26\">二十六 · 负载配方与失效边界：什么时候该关掉协同筛选</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-27\">二十七 · 硬件档位：按保留率与 SLO 反推 SM 与带宽配比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-28\">二十八 · 并行拓扑：TP 沿 d 切、视觉侧不跨 stage</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-29\">二十九 · 量化方案：打分保精度、预填吃低精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-30\">三十 · KV 策略：只为保留 token 分配，按页粒度回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-31\">三十一 · 调度参数与可复现配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-32\">三十二 · 与相邻方案的部署边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-33\">三十三 · 保留率不是旋钮，是契约：失效边界与代价核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-34\">三十四 · 预填时延的四项分解与“谁在付钱”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-35\">三十五 · 显存与 KV cache：压缩比不等于显存节省比</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-36\">三十六 · 带宽与通信：压缩改变了集合通信的消息尺寸</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-37\">三十七 · 功耗：算力节省与固定开销的抵消</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-38\">三十八 · 尾延迟：保留率自适应失败是长尾的主因</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-39\">三十九 · 规模上去以后哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-40\">四十 · 规模上去以后，先崩的是打分与合并的串行段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-41\">四十一 · 精度失效的三条路径与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-42\">四十二 · OOM 的两种来源：预算漂移与 KV 峰值叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-43\">四十三 · 批抖动与路由不均：保留率作为调度维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-44\">四十四 · 尾延迟尖刺的归因树</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-45\">四十五 · 监控指标与回滚策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-46\">四十六 · 诊断工具链与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-47\">四十七 · 对照维度：先看“压缩发生在哪一层”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-48\">四十八 · 决策表：五类候选的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-49\">四十九 · 用预填代价公式做取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-50\">五十 · 与量化类、投机类的正交关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-51\">五十一 · 适用条件清单与不适用信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-52\">五十二 · 组合顺序：把同族算法排成流水线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vitcop-vlm-prefill-sec-53\">五十三 · 选型边界：什么时候该用 ViTCoP，什么时候该换别的路</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:522px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 522.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">图像经 ViT 切 patch 并编码为视觉 token 序列</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">用文本指令的嵌入对视觉 token 做跨模态相关性打分</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按分数保留 top-k 视觉 token，其余按空间邻接合并为少量摘要 t…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">压缩后的视觉 token 与文本 token 拼接送入 LLM 预填</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"440.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV cache 仅对保留 token 分配，解码阶段复用</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-1\">一 · 一次 TTFT 雪崩：预填被视觉 token 淹没</h3>\n<p>某 OCR 辅助的文档问答服务在 Blackwell 单机上跑一个中等规模 VLM，图像侧走 448×448 切 patch，视觉 token 数量是文本指令的十几倍。上线初期只用短问句做压测，TTFT 稳定在可接受区间；真实流量进来后，前端把整页扫描件连同多段追问一起送进服务，文本侧变长、图像侧不变，但排队现象突然出现：P99 TTFT 从秒级滑到十几秒，连续批处理队列被单个长请求占满，后续短请求全部被拖死。根因不是解码慢，而是预填阶段被视觉 token 的算力与带宽吃掉：视觉编码器把整页切成大量 patch token，LLM 预填要对这些 token 做完整的 QKV 投影与前馈，KV cache 也要为它们逐层写入，而其中真正与问题相关的只有少数区域。这就是 ViTCoP 要解决的推理问题——不是模型不会答，而是预填的开销结构被冗余视觉 token 支配。</p>\n<p>把预填代价写成可核算的形式，问题立刻清楚：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>式中 $N_{\\text{vis}}'$ 是进入 LLM 的视觉 token 数，$d$ 为隐藏维度，$N_{\\text{txt}}$ 为文本 token 数，$B_{\\text{kv}}$ 为每 token 的 KV 字节数。第一项是视觉 token 自身的投影与前馈 FLOPs，第二项是视觉与文本的交叉注意力项，第三项是 KV 写入的带宽项。三项全部与 $N_{\\text{vis}}'$ 成正比，这意味着在视觉 token 远多于文本 token 的负载里，TTFT 几乎由 $N_{\\text{vis}}'$ 单独决定。事故中的服务没有做任何筛选，$N_{\\text{vis}}'$ 等于全部 patch 数，于是算力项和带宽项同时饱和；Blackwell 的 tcgen05 与 TMEM 能把矩阵乘效率拉高，但拉不高“做了无用功”的比例，带宽侧的 KV 写入更不会因为 MMA 变快而消失。这就是为什么单纯换更快的 kernel 救不了这类事故。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-2\">二 · 算法边界：一次性筛选，不碰解码与拓扑</h3>\n<p>ViTCoP 的定位非常窄：它只在视觉编码器输出与 LLM 预填之间插入一次视觉-文本语义协同打分，按文本指令相关性对视觉 token 做一次性筛选与合并，把进入 LLM 的视觉 token 压到预算内。数据流顺序是固定的：ViT 切 patch 并编码为视觉 token 序列；用文本指令嵌入对每个视觉 token 做跨模态相关性打分；按分数保留 top-$k$，其余按空间邻接合并为少量摘要 token；压缩后的视觉 token 与文本 token 拼接送入 LLM 预填；KV cache 只对保留 token 分配，解码阶段复用。打分与保留可写为</p>\n<div class=\"formula\">$$s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j),\\quad \\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$$</div>\n<p>其中 $\\mathbf{e}_t$ 为文本指令嵌入，$\\mathbf{v}_j$ 为第 $j$ 个视觉 token 表示，$\\mathcal{K}$ 为保留集合。这个式子的工程含义是：压缩比由 $k$ 直接给定，而不是由模型自己学出来，因此容量规划可以把 $k$ 当作显式旋钮，按 SLO 反推预算。</p>\n<p>它明确不解决的问题有三类。第一，它不改变阶段并行拓扑：分离式预填/解码的部署形态、PD 比例、KV 传输路径都不在它的作用范围内，跨阶段并行服务那条线动的是拓扑，ViTCoP 动的是预填内部的 token 数量。第二，它不进入 LLM 浅层做二次注意力显著性压缩——DUET-VLM 那类双阶段方案会在 LLM 内部再看一遍注意力，ViTCoP 只在编码器出口做一次判定，因此它没有“用解码侧信号回补筛选”的能力。第三，它不处理量化与数值精度：NVFP4/FP8 的算子选择、量化感知剪枝是别的条目的主题，ViTCoP 是训练无关的推理侧插件，不引入新的数值格式。把边界说清楚很重要，因为工程上最常见的误用就是拿它去救“解码太慢”或“显存不够放权重”的问题，而那两类问题的瓶颈根本不在预填 token 数上。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-3\">三 · 收益结构与代价结构必须成对核算</h3>\n<p>收益侧是直接的：预填 FLOPs 与 KV 写入量同时按保留率缩减，TTFT 随保留率近似线性下降。用上面的公式看，若把 $N_{\\text{vis}}'$ 从全量压到 $k$，三项同步缩小，其中带宽项缩小得最“干净”，因为它不依赖 FLOPS$_{\\text{eff}}$ 的实际达成率。KV cache 只对保留 token 分配，意味着显存占用与可并发批数同时改善——这一点在 NVL72 这类高带宽互联但显存仍按卡切的系统里尤其值钱，因为批大小往往是被 KV 显存而不是被算力卡住的。</p>\n<p>代价侧有两处必须在设计文档里写死。其一是相关性打分依赖文本指令：指令模糊、或长文档里问题指向不明时，$\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 的区分度下降，top-$k$ 的保留率无法自适应，关键视觉 token 会被误删。其二是空间邻接合并出的摘要 token 会损失细粒度位置信息，OCR 与定位类任务精度明显下降。这两条不是“偶发误差”，而是结构性的：打分函数只有一个文本锚点，长文档里同一段文字可能对应多个语义，单一 $\\mathbf{e}_t$ 无法区分；合并操作把邻域压成一个向量，坐标信息在池化中不可逆地丢失。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>保留率高</th><th>保留率低</th></tr></thead><tbody><tr><td>TTFT</td><td>接近全量预填，事故场景不可接受</td><td>近似线性下降，SLO 可守</td></tr><tr><td>KV 显存与批大小</td><td>KV 写入大，并发批受限</td><td>KV 缩小，批大小可上调</td></tr><tr><td>OCR/定位精度</td><td>细粒度信息基本保留</td><td>摘要 token 丢失坐标，精度下降</td></tr><tr><td>解码稳定性</td><td>上下文充足</td><td>上下文不足，易重复生成或答非所问</td></tr></tbody></table>\n<p>第三行与第四行是联动的：保留率过低时 KV cache 确实小了，但解码阶段上下文不足，模型会重复生成或答非所问——这不是精度指标的轻微下滑，而是可用性问题。因此保留率不能当成“越低越省”的单调旋钮，它是一个带下界的参数，下界由任务类型决定。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-4\">四 · 适用边界的判定方法：按任务而非按模型</h3>\n<p>适用与否不取决于用哪个 VLM，而取决于请求形态。ViTCoP 适用于“图像加文本指令”的 VLM 预填加速，尤其适合指令明确的查询：用户问“图中红色阀门在哪”“这张发票的总额是多少”，文本锚点清晰，打分区分度高，$k$ 可以压得比较激进而精度损失可控。反过来，OCR 全页转写、版面元素定位、密集小目标的计数与坐标回归这类依赖细粒度空间信息的任务不适用——它们需要的恰恰是被合并掉的那些邻域细节。</p>\n<p>工程上可以用一个轻量判定流程把请求分流，而不是全局开关：</p>\n<ul>\n<li>解析请求的任务标签：问答、摘要、分类走压缩路径；OCR、定位、计数走全量路径。</li>\n<li>对走压缩路径的请求估计指令明确度，例如文本指令长度与实体密度，明确度低时自动上调 $k$。</li>\n<li>按当前批的 SLO 余量决定 $k$：TTFT 余量大就保守，余量小才激进压缩。</li>\n<li>压缩路径的输出做一次轻量自检（如答案是否引用了被删区域），失败则回退全量重跑，把回退率作为监控指标。</li>\n</ul>\n<p>这套分流的系统代价是可核算的：压缩路径省下的预填时间必须大于判定与自检的开销，否则插件本身成为延迟源。在 Blackwell 上，判定逻辑应放在 CPU 侧或极小的 GPU kernel 里，避免打断预填流水；回退重跑则要占用额外一次预填的算力与 KV 写入，因此回退率必须压得很低，否则整体吞吐反而下降。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-5\">五 · 为什么训练无关是它最重要的稳定性属性</h3>\n<p>ViTCoP 作为推理侧插件接入现有 VLM 服务栈，不训练、不改权重、不动 tokenizer。这个属性在事故复盘里的价值常被低估：预填雪崩发生时，团队没有时间重训或做校准，需要一个能当天上线、能按请求灰度、能一键回退的开关。训练无关意味着它可以按请求粒度启用，A/B 对比直接在同一份权重上做，精度回归的归因也干净——精度掉了就是筛选造成的，不会和训练数据分布变化混在一起。</p>\n<p>但训练无关也意味着它不能“学会”补偿自己的损失。打分函数是固定的余弦相似度，合并策略是固定的空间邻接，没有任何可学习参数去适配特定领域。因此在垂直领域（医疗影像、工业质检）里，如果文本指令的措辞与视觉内容的语义距离天然较大，余弦打分的排序质量会下降，此时正确的做法是收紧适用边界、提高 $k$，而不是指望插件自适应。这一点与量化感知剪枝那条线形成对照：后者把量化误差纳入剪枝决策，需要训练或校准；ViTCoP 用集成风险换取了部署速度，代价是精度上限被固定策略锁死。</p>\n<p>容量规划上还应把保留率写进 SLO 契约：TTFT 目标反推出 $k$ 的上界，精度目标反推出 $k$ 的下界，两者夹出的区间就是该服务可用的保留率窗口。窗口为空时，说明这个服务的请求形态不适合 ViTCoP，应当走全量预填并靠批调度与分离式部署去压 TTFT，而不是硬调 $k$。事故复盘最后落到的那条工程判断是：先确认瓶颈在预填 token 数，再确认任务不依赖细粒度空间信息，两个条件同时成立才启用压缩；只满足一个，插件就从加速手段变成精度事故的来源。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-6\">六 · 失效边界：指令模糊与细粒度任务上的误删代价</h3>\n<p>一次线上事故足以说明边界在哪里：文档问答服务接入该插件后，把保留率压到很低以换取 TTFT，结果一批扫描件工单的字段抽取请求开始答非所问——模型把相邻两栏的金额读串，或直接跳过表格右下角的合计行。根因不是打分器坏了，而是文本指令只写了“提取关键信息”，嵌入与视觉 token 的余弦相似度分布过于平坦，top-$k$ 截断等于按噪声删 token；被删的恰恰是空间上孤立、语义上不突出的数字区域。随后空间邻接合并把剩余 patch 压成摘要 token，位置精度进一步丢失，OCR 与定位类任务首先崩掉。</p>\n<p>打分与筛选的形式是 $$s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j),\\quad \\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$$，其中 $\\mathbf{e}_t$ 为指令嵌入、$\\mathbf{v}_j$ 为第 $j$ 个视觉 token 表示。该式暴露两个失效条件：其一，$s_j$ 的区分度由 $\\mathbf{e}_t$ 决定，指令模糊或长文档场景下分数趋于同质，TopK 的边界由噪声而非语义决定，保留率无法自适应；其二，$k$ 是全局预算而非按任务分配，细粒度任务需要的高分辨率 patch 与查询型任务需要的语义 patch 争抢同一配额。KV cache 只对保留 token 分配，看似省了显存，但解码阶段上下文不足会诱发重复生成，等于用解码步数换预填时延。</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>保留率策略</th><th>主要风险</th></tr></thead><tbody><tr><td>指令明确的单图查询</td><td>可压低，收益直接</td><td>低</td></tr><tr><td>模糊指令、多图长文档</td><td>需保守，收益收窄</td><td>关键 token 误删</td></tr><tr><td>OCR、定位、表格抽取</td><td>不宜启用合并</td><td>空间精度下降</td></tr></tbody></table>\n<p>系统代价要按账算清：预填时延近似为 $$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$，$N_{\\text{vis}}'$ 是压缩后的视觉 token 数，收益随保留率近似线性，但打分本身要额外读一遍视觉 token 与指令嵌入，属于纯增开销；合并摘要 token 还引入一次额外写回。它削减的是预填 FLOPs 与 KV 写入，不改变阶段并行拓扑，也不解决解码阶段的带宽瓶颈——若线上瓶颈在 decode 的 KV 读取而非 TTFT，这套插件的净收益会被打分开销吃掉。工程判断是：按任务类型分路，OCR/定位走不合并路径，模糊指令场景设保留率下限并以精度回归门禁守住，别把全局统一保留率当成默认配置。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-7\">七 · 图像入口：patch 切分与 ViT 编码的代价锚点</h3>\n<p>ViTCoP 的数据流从像素开始。图像被切成固定尺寸 patch，经 ViT 主干编码为视觉 token 序列，输出是形状为 <span class=\"inline-math\">N<sub>vis</sub> × d</span> 的张量，其中 <span class=\"inline-math\">N<sub>vis</sub></span> 是 patch 数、<span class=\"inline-math\">d</span> 是隐藏维。这一步的输入是原始分辨率图像，输出是尚未与文本发生任何交互的纯视觉表示。代价集中在两处：ViT 自身的注意力与前馈计算随 <span class=\"inline-math\">N<sub>vis</sub></span> 平方增长；视觉 token 张量要落回显存供后续打分读取，占用 <span class=\"inline-math\">N<sub>vis</sub>·d·B<sub>elem</sub></span> 的容量。对高分辨率输入，<span class=\"inline-math\">N<sub>vis</sub></span> 可达文本 token 数的数倍，这正是后续所有压缩动作的动机来源。</p>\n<p>关键工程判断是：ViT 编码本身不在本算法的削减范围内。ViTCoP 只在视觉编码器输出与 LLM 预填之间插入筛选，因此 ViT 的算力与显存开销是固定成本，压缩收益全部体现在 LLM 预填侧。这意味着当图像分辨率极高、ViT 成为瓶颈时，本算法的边际收益被稀释；反之当 LLM 预填占主导（长文本指令、大 batch）时收益显著。接入时应先测量 ViT 与 LLM 预填的耗时占比，再决定是否启用。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-8\">八 · 跨模态打分：文本嵌入与视觉 token 的余弦对齐</h3>\n<p>打分步骤的输入是文本指令嵌入 <span class=\"inline-math\">e<sub>t</sub></span> 与每个视觉 token 表示 <span class=\"inline-math\">v<sub>j</sub></span>，输出是长度 <span class=\"inline-math\">N<sub>vis</sub></span> 的相关性分数向量。机制写作：</p>\n<div class=\"formula\">$$s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j),\\quad \\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$$</div>\n<p>其中 <span class=\"inline-math\">K</span> 为保留 token 集合，<span class=\"inline-math\">k</span> 由保留率与 <span class=\"inline-math\">N<sub>vis</sub></span> 共同决定。实现上这是一次矩阵-向量乘：把 <span class=\"inline-math\">e<sub>t</sub></span> 与 <span class=\"inline-math\">N<sub>vis</sub>×d</span> 的视觉矩阵做归一化点积，计算量约 <span class=\"inline-math\">N<sub>vis</sub>·d</span> 次乘加，相对 LLM 预填的 <span class=\"inline-math\">d<sup>2</sup></span> 项可忽略，但需要把整个视觉张量从显存读一遍，是一次纯带宽操作。在 Blackwell 上这次读取走 HBM，带宽开销为 <span class=\"inline-math\">N<sub>vis</sub>·d·B<sub>elem</sub></span> 字节；若视觉张量以 FP8 存放，读取量减半，打分延迟随之下降。</p>\n<p>打分的质量决定一切。指令明确时（“图中红色汽车的车牌号是多少”），<span class=\"inline-math\">e<sub>t</sub></span> 与车牌区域 token 的余弦相似度形成明显区分度，top-k 能稳定命中关键 patch。指令模糊或长文档场景下，<span class=\"inline-math\">e<sub>t</sub></span> 是整段文本的池化表示，语义被平均化，分数分布趋于平坦，top-k 退化为近似随机采样——这是本算法最本质的失败模式，且无法靠调参修复，只能靠外部策略（如按指令分段多次打分）缓解。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-9\">九 · 保留与合并：top-k 选择加空间邻接摘要</h3>\n<p>选择步骤的输出分两部分：保留集 <span class=\"inline-math\">K</span> 中的 token 原样进入后续拼接；被淘汰的 token 不直接丢弃，而按空间邻接关系合并为少量摘要 token。合并的输入是被淘汰 token 的表示与其 patch 坐标，输出是数量远小于淘汰数的摘要向量。空间邻接意味着合并按网格邻域聚类，同一局部区域内的 token 求池化，保留粗粒度布局信息。</p>\n<p>这一步的代价是双面的。收益侧：进入 LLM 的视觉 token 数从 <span class=\"inline-math\">N<sub>vis</sub></span> 降到 <span class=\"inline-math\">N<sub>vis</sub>′ = k + m</span>（<span class=\"inline-math\">m</span> 为摘要 token 数），预填 FLOPs 中的视觉项按 <span class=\"inline-math\">N<sub>vis</sub>′</span> 线性缩减。损失侧：合并把多个 patch 的位置信息压成一个向量，细粒度空间关系不可恢复。OCR 需要字符级位置、定位任务需要精确边界框，这类任务对合并极其敏感，精度下降是结构性的而非偶然。工程上应把合并比例作为可调旋钮：对 OCR/定位请求设 <span class=\"inline-math\">m=0</span> 或极小，仅做 top-k 保留；对通用问答可放大 <span class=\"inline-math\">m</span> 换取更高压缩率。</p>\n<p>合并操作本身在 GPU 上是一次 scatter/gather，需要按聚类索引写入输出缓冲，访存模式不规则，容易产生 bank 冲突。实现时应预生成聚类索引表并复用，避免每请求重新计算邻接关系。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-10\">十 · 拼接与 LLM 预填：压缩后 token 序列的算力账</h3>\n<p>压缩后的视觉 token 与文本 token 拼接，形成 LLM 预填的输入序列，长度 <span class=\"inline-math\">N<sub>vis</sub>′ + N<sub>txt</sub></span>。预填阶段的计算由两部分构成：视觉 token 自身的前馈与投影（<span class=\"inline-math\">4N<sub>vis</sub>′d<sup>2</sup></span> 量级），以及视觉与文本之间的注意力交互（<span class=\"inline-math\">2N<sub>vis</sub>′N<sub>txt</sub>d</span> 量级）。总时延可写为：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>第一项是算力受限部分，第二项是 KV 写入的带宽受限部分。两项都对 <span class=\"inline-math\">N<sub>vis</sub>′</span> 线性，因此 TTFT 随保留率近似线性下降——这是本算法最直接的收益承诺。注意第二项中 <span class=\"inline-math\">B<sub>kv</sub></span> 是每 token 的 KV 字节数，在 Blackwell 上若 KV 以 FP8 存放则减半，带宽项相应缩小。</p>\n<p>在 SM100 上，预填的矩阵乘由 tcgen05 指令驱动，累加器驻留 TMEM，2-SM MMA 模式可让两个 SM 协同处理同一 tile。压缩带来的序列缩短直接减少 MMA 的 tile 数量，是吞吐与延迟同时受益的少数优化之一。但需注意：序列变短后单请求的并行度下降，若 batch 内请求长度差异大，短序列请求可能无法填满 SM，此时应依赖连续批处理把多个请求的预填拼批，而不是单纯追求单请求压缩率。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-11\">十一 · KV cache 分配与解码复用：显存账与上下文风险</h3>\n<p>预填完成后，KV cache 只对进入 LLM 的 token 分配，即 <span class=\"inline-math\">N<sub>vis</sub>′ + N<sub>txt</sub></span> 个位置，而非原始的 <span class=\"inline-math\">N<sub>vis</sub> + N<sub>txt</sub></span>。显存占用按保留率线性缩减，这对大 batch 服务是实质性收益：KV 池容量决定并发上限，压缩直接抬高可服务的并发请求数。解码阶段复用这批 KV，每步只追加一个新 token 的 KV，不再触碰视觉部分。</p>\n<p>风险在于保留率过低时的解码行为。视觉上下文不足会让模型在生成时缺乏 grounding，表现为重复生成、答非所问或凭空编造细节。这不是精度指标的轻微下降，而是可用性问题。工程上应设置保留率下限，并对低置信度打分分布（分数方差小）的请求自动提高保留率，用少量 TTFT 换取解码正确性。该自适应逻辑本身很轻：只需在打分后计算分数分布的离散度，一次 reduction 即可，代价可忽略。</p>\n<p>另一处细节是 KV 的物理布局。压缩后序列长度不再是固定值，分页式 KV 管理（PagedAttention 类）天然适配变长序列，但块表碎片化会增加元数据开销；若采用连续分配，则需按最大保留率预留，抵消部分显存收益。选择分页管理更符合本算法的变长特性。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-12\">十二 · 步骤间的耦合与流水线排布</h3>\n<p>把五个步骤串起来看，ViT 编码是算力密集，打分是带宽密集，合并是访存不规则，预填是算力与带宽混合，KV 分配是元数据操作。这种异构性决定了流水线排布：打分必须等 ViT 输出全部就绪，无法与 ViT 重叠；但打分可以与同一 batch 内其他请求的 LLM 预填重叠——当一个请求在打分时，另一个已完成压缩的请求可以占用 SM 做预填。在 Blackwell 上这可借助多流（multi-stream）实现，把打分放在低优先级流，预填放在高优先级流，用计算与带宽的互补填满硬件。</p>\n<p>合并步骤与打分之间存在数据依赖但无算力冲突，可融合为单 kernel：打分后立即在片上完成 top-k 与邻域池化，避免视觉张量二次落回 HBM。融合后该阶段的 HBM 流量从两次读写降为一次读加一次小规模写，对带宽受限的打分阶段是直接收益。实现难点是 top-k 的排序需要全局同步，可用分块 top-k 加跨块归并的两段式策略，在块内用寄存器排序、块间用共享内存归并。</p>\n<p>最后一个工程判断：本算法作为推理侧插件接入，训练无关，意味着它不改变模型权重与图结构，只改变输入序列长度。这让它可以与量化、并行拓扑、批调度独立组合，但也意味着它无法利用模型内部的注意力显著性信息——那需要进入 LLM 浅层，属于另一条技术路线。接入时应把它定位为预填入口的序列整形层，收益上界由保留率决定，风险下界由指令明确度决定。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-13\">十三 · 筛选发生在哪一段：一次性插件的边界与代价</h3>\n<p>ViTCoP 的协同打分不是嵌在 LLM 浅层注意力里的二次压缩，而是插在视觉编码器输出与 LLM 预填入口之间的一次性关卡。这意味着它的收益上限被这段数据流的物理位置锁死：它只能削减进入 LLM 的视觉 token 数量，无法改变视觉编码器本身的 FLOPs——ViT 仍要把整幅图切成 patch 并全部编码完，才能拿到每个视觉 token 的表示 $\\mathbf{v}_j$ 去和指令嵌入 $\\mathbf{e}_t$ 做余弦打分。所以当图像分辨率极高、patch 数量巨大时，编码器这一段开销原封不动留在关键路径上，压缩只对预填阶段的注意力与 FFN 生效。用公式看更清楚：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>式中 $N_{\\text{vis}}'$ 是压缩后进入 LLM 的视觉 token 数，$N_{\\text{txt}}$ 为文本 token 数，$d$ 为隐维，$B_{\\text{kv}}$ 为每 token 的 KV 字节量。第一项随 $N_{\\text{vis}}'$ 线性缩放，第二项是 KV 写入的带宽代价，同样线性。保留率从 1 降到 $k/N_{\\text{vis}}$ 时，这两项同步缩小，TTFT 近似线性下降——但公式里没有出现编码器那一项，这正是该方案的天花板：它加速的是预填，不是编码。工程上要判断值不值得接，先量出编码器与预填在 TTFT 中的占比，若编码器占大头，单靠这一层筛选的端到端收益会被摊薄。</p>\n<p>失效条件集中在打分的区分度上。打分与保留写作 $s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j)$，$\\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$。当文本指令明确（“图中红色消防栓在哪”），$\\mathbf{e}_t$ 与相关 patch 的表示有明显夹角差异，top-$k$ 能干净地切出目标区域；当指令模糊（“描述这张图”）或输入是长文档多图场景，$\\mathbf{e}_t$ 几乎与所有视觉 token 等距，分数分布趋于平坦，top-$k$ 退化为近似随机采样，关键 token 被误删的概率上升，而保留率 $k$ 是静态预算、无法随指令歧义度自适应。第二类失效来自合并：被淘汰的 token 按空间邻接压成少量摘要 token，位置编码被聚合掉，OCR 的行内字符对齐、目标定位的边界框回归都依赖细粒度空间坐标，摘要 token 提供不了这种精度，精度下降是结构性的而非调参可解。因此这条路径的适用边界应写成“指令明确的图像问答类预填加速”，OCR 与定位任务应绕开或对保留率取保守值。</p>\n<p>系统代价还有一笔隐性账：KV cache 只对保留 token 分配，显存占用随保留率下降，这是收益；但解码阶段复用的是被压缩后的上下文，保留率设得过低时，模型看到的视觉证据不足，会出现重复生成或答非所问——这不是精度指标的轻微下滑，而是输出质量的断崖。容量规划上应把保留率当作一个 SLO 旋钮而非免费参数：它同时调节 TTFT、KV 显存与答案保真度三个量，三者不是同向的。工程判断是，把保留率与指令类型绑定——明确查询走低保留率换 TTFT，开放描述与文档理解走高保留率保质量，并在服务栈里对 OCR/定位请求直接旁路该插件，而不是指望一个全局 $k$ 覆盖所有负载。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-14\">十四 · 预填时延公式的四项分解</h3>\n<p>本部分的核心是把 ViTCoP 的收益写成可核算的时延表达式，而不是停留在“减少 token 所以更快”的定性说法。给定公式：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>逐项读法如下。第一项 $4N_{\\text{vis}}' d^2$ 是视觉 token 在 LLM 预填中经过线性层（QKV 投影与输出投影合计约四次 $d\\times d$ 矩阵乘）所付出的算力，系数 4 来自每 token 每层两组投影的乘加计数；第二项 $2N_{\\text{vis}}' N_{\\text{txt}} d$ 是视觉 token 与文本 token 之间的注意力交互代价，$2$ 对应 QK^T 与 AV 两次乘加，$N_{\\text{txt}}$ 是文本侧 token 数。两项相加除以 $\\text{FLOPS}_{\\text{eff}}$（有效算力，已扣除 occupancy 与流水气泡）得到算力受限部分。第三项 $\\frac{2N_{\\text{vis}}' d B_{\\text{kv}}}{\\text{BW}}$ 是 KV 写入的带宽代价：每 token 每层写 K 与 V 两份 $d$ 维向量，$B_{\\text{kv}}$ 为每 token 的 KV 字节数（含层数与精度因子），除以可用带宽 $\\text{BW}$。关键在于 $N_{\\text{vis}}'$ 同时出现在三项的分子上，因此时延对保留 token 数是分段近线性的：算力项与带宽项各自线性，二者谁占主导取决于 $\\text{FLOPS}_{\\text{eff}}/\\text{BW}$ 的比值与 $B_{\\text{kv}}$ 的大小。</p>\n<p>推导的关键一步是把 $N_{\\text{vis}}'$ 从原始视觉 token 数 $N_{\\text{vis}}$ 解耦为预算变量。设保留率为 $\\rho$，则 $N_{\\text{vis}}' = \\rho N_{\\text{vis}} + m$，其中 $m$ 是合并产生的摘要 token 数（远小于 $N_{\\text{vis}}$，通常为个位到十位量级）。代入后对 $\\rho$ 求偏导：</p>\n<div class=\"formula\">$$\\frac{\\partial T_{\\text{prefill}}}{\\partial \\rho}\\approx N_{\\text{vis}}\\left(\\frac{4d^2+2N_{\\text{txt}}d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2dB_{\\text{kv}}}{\\text{BW}}\\right)$$</div>\n<p>这个偏导是常数，正是“TTFT 随保留率近似线性下降”的数学来源。工程含义是：调低 $\\rho$ 的边际收益固定，不存在饱和点，因此保留率应当由精度约束而非性能曲线来定。举例来说，一张切成数百个 patch 的图像在 $d$ 较大时，$4d^2$ 项主导算力部分，此时把 $\\rho$ 从高位压到低位，节省的时间几乎全部来自第一项；而在 $d$ 较小、$N_{\\text{txt}}$ 很长的长文档问答里，第二项 $2N_{\\text{vis}}'N_{\\text{txt}}d$ 会反超，说明视觉 token 与长文本的交叉注意力才是瓶颈，压缩视觉侧仍然有效但收益结构不同。代价侧要同时记账：$\\rho$ 过低会让 KV cache 变小、显存压力下降，但解码阶段上下文不足，出现重复生成或答非所问，这部分损失不进入时延公式，却进入质量账本。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-15\">十五 · 相关性打分的可实现形式</h3>\n<p>打分公式为 $s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j)$，$\\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$，其中 $\\mathbf{e}_t$ 是文本指令嵌入、$\\mathbf{v}_j$ 是第 $j$ 个视觉 token 表示。实现上有三个必须落地的细节。第一，$\\mathbf{e}_t$ 与 $\\mathbf{v}_j$ 必须处于同一可比空间：ViT 输出的视觉 token 与 LLM 的词嵌入维度、归一化方式往往不一致，直接做余弦会退化为噪声。可行做法是在视觉编码器输出后接一个轻量线性投影到文本嵌入维度，再做 L2 归一化；该投影可用文本侧嵌入的统计量做无监督校准，保持训练无关的插件属性。第二，余弦相似度的计算是 $N_{\\text{vis}}\\times d$ 的一次矩阵向量乘，代价为 $2N_{\\text{vis}}d$ 次乘加，相对于预填本身可忽略，但它是一次同步点——打分完成前无法启动 LLM 预填，因此打分核必须与 ViT 尾段流水重叠，否则会引入固定启动延迟。第三，TopK 的 $k$ 应由预算反解：$k = \\lfloor \\rho N_{\\text{vis}}\\rfloor$，而 $\\rho$ 来自 SLO 侧对 TTFT 的约束，通过上面的偏导式换算得到。</p>\n<p>伪代码落到可实现层面，按数据流写成如下思路（非 <code>&lt;pre&gt;</code> 形式，以步骤描述）：视觉编码得到 $\\mathbf{V}\\in\\mathbb{R}^{N_{\\text{vis}}\\times d_v}$；投影归一化得 $\\hat{\\mathbf{V}}$；取指令嵌入 $\\mathbf{e}_t$ 归一化后与 $\\hat{\\mathbf{V}}$ 做一次 GEMM 得分数向量 $\\mathbf{s}$；对 $\\mathbf{s}$ 做 top-k 得到索引集合 $\\mathcal{K}$ 与补集 $\\mathcal{K}^c$；对 $\\mathcal{K}^c$ 按 patch 网格的空间邻接做聚类合并，每个连通簇输出一个摘要 token（表示取簇内均值再投影）；最终序列为 $\\mathbf{V}[\\mathcal{K}] \\oplus \\mathbf{V}_{\\text{sum}}$ 与文本 token 拼接。合并步骤的代价是一次按网格索引的 gather 与均值归约，显存上是 $O(N_{\\text{vis}}d)$ 的读写，不引入额外的大矩阵乘。一个具体例子：指令为“图中红色交通标志的位置”，打分会把与红色、标志形状相关的 patch 推到前列，天空与路面的大片 patch 落入补集并被合并成少量摘要 token，进入 LLM 的视觉 token 数被压到预算内，而摘要 token 仍保留“画面下半部是路面”这类粗粒度上下文。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-16\">十六 · 合并算子与空间邻接的代价账</h3>\n<p>合并不是免费的抽象步骤，它决定了精度损失落在哪里。按空间邻接合并意味着补集 token 按 patch 网格的二维邻接关系聚类，簇内做均值池化。这一步的算力代价可写成 $O(N_{\\text{vis}}' d)$ 级别的归约，真正的问题是信息代价：均值池化把簇内位置信息压成一个向量，细粒度空间关系（字符笔画、边框坐标）不可恢复。因此 OCR 与定位类任务的精度下降不是偶发，而是算子结构的必然结果。工程判断是：对这类任务应把 $\\rho$ 设到接近 1 或直接旁路 ViTCoP，把压缩留给其他环节；对指令明确的查询类任务，$\\rho$ 可以压低，因为答案所需的证据集中在少数 patch 上，补集只承担背景上下文。</p>\n<p>从显存与带宽看，合并摘要 token 的收益是双份的：KV cache 仅对保留 token 分配，摘要 token 也按少量条目计入，因此 KV 占用随 $N_{\\text{vis}}'$ 线性缩小；同时 KV 写入带宽项 $\\frac{2N_{\\text{vis}}'dB_{\\text{kv}}}{\\text{BW}}$ 同步缩小。但要注意解码阶段的复用语义：KV 只对保留 token 建立，意味着解码时模型看到的视觉上下文就是压缩后的那一份，不存在“解码时再取回被删 token”的路径。这解释了失败模式中“保留率过低导致重复生成或答非所问”——解码器缺少足够证据时会退化为语言先验驱动的复读。一个可操作的稳定性技巧是把 $\\rho$ 与指令长度挂钩：长文档场景下 $\\mathbf{e}_t$ 是多句甚至多段文本的池化嵌入，区分度低，此时应提高 $\\rho$ 或改用分段打分（按句切分指令、对每段各取 top-k 再并集），用少量额外打分算力换取保留集合的召回。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-17\">十七 · 预算反解与批内异构</h3>\n<p>把公式用于调度需要一次反解：给定 TTFT 目标 $T^\\star$，求最大 $\\rho$。由时延式线性于 $N_{\\text{vis}}'$，可直接解出</p>\n<div class=\"formula\">$$N_{\\text{vis}}'^{\\star}=\\frac{T^\\star}{\\dfrac{4d^2+2N_{\\text{txt}}d}{\\text{FLOPS}_{\\text{eff}}}+\\dfrac{2dB_{\\text{kv}}}{\\text{BW}}}$$</div>\n<p>再减去摘要 token 数 $m$ 并除以 $N_{\\text{vis}}$ 得 $\\rho^\\star$。这个反解在连续批处理里必须按请求逐个做，因为同一批内不同请求的 $N_{\\text{txt}}$ 差异很大：一个短指令的请求算力项小、可承受更低保留率；一个长文档请求的交叉注意力项大，同样 $\\rho$ 下时延更高。若整批用统一 $\\rho$，批的 TTFT 由最慢请求决定，快请求的算力被浪费。可实现的策略是批内异构保留率：每个请求独立算 $\\rho^\\star$ 并各自 TopK，拼 batch 时按压缩后的实际 token 数做变长打包。代价是 TopK 与合并核的调用次数随批内请求数上升，打分核的启动开销变成吞吐侧的主要摩擦；缓解办法是把打分与合并做成融合核，一次处理整批的视觉 token 并在核内完成分段 TopK。</p>\n<p>另一个工程判断涉及与 DUET-VLM 的分工：ViTCoP 只在视觉编码器输出与 LLM 预填之间做一次性筛选与合并，不进入 LLM 浅层做二次注意力显著性压缩。这意味着它的预算在预填开始前就已固定，无法利用浅层注意力反馈修正保留集合。因此在指令模糊的场景下，一次性打分的区分度不足是结构性缺陷，而非调参问题；此时把 $\\rho$ 抬高是唯一稳妥的兜底，代价是 TTFT 收益收窄。相对地，它削减的是预填 FLOPs 而非改变阶段并行拓扑，所以接入时不触碰预填/解码的分离式部署形态，集成风险低——这也是它作为训练无关插件的稳定性来源。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-18\">十八 · 数值精度与硬件落点的耦合</h3>\n<p>公式里的 $\\text{FLOPS}_{\\text{eff}}$ 与 $\\text{BW}$ 不是器件峰值，而是当前精度配置下的有效值，这使 $\\rho^\\star$ 随量化方案漂移。若视觉侧投影与 LLM 预填走 FP8 或 NVFP4，$\\text{FLOPS}_{\\text{eff}}$ 上升，算力项变小，时延更多由带宽项 $\\frac{2N_{\\text{vis}}'dB_{\\text{kv}}}{\\text{BW}}$ 决定；此时继续压低 $\\rho$ 的收益主要来自 KV 写入减少，而非矩阵乘减少。反过来，若 KV cache 以低精度存储，$B_{\\text{kv}}$ 下降，带宽项收窄，算力项重新主导。工程含义是：保留率的调优点应随精度档位重算，不能把一套 $\\rho$ 写死进服务配置。打分核本身的精度要求反而低——余弦相似度对量化不敏感，用 FP8 甚至更低精度做打分不会显著改变 TopK 排序，这为把打分核放在低精度通路、把合并后的表示保留在较高精度提供了空间。</p>\n<p>硬件落点上，打分是一次 $N_{\\text{vis}}\\times d$ 的矩阵向量乘，天然适合在 ViT 尾段同一流上做，避免额外的 kernel launch 与显存往返；合并的 gather 与均值归约是访存密集型，应尽量与打分融合以减少一次全量读写。TMEM 与 2-SM MMA 这类 Blackwell 特性对本环节的收益有限，因为打分与合并都不是大矩阵乘；真正受益的是压缩后进入 LLM 预填的那部分 token——$N_{\\text{vis}}'$ 变小后，预填的 GEMM 形状变窄，tcgen05 路径的利用率反而更需要关注，窄形状下要保证 MMA 的 tile 填充率，否则 $\\text{FLOPS}_{\\text{eff}}$ 会因形状退化而下降，抵消一部分压缩收益。这是一个容易被忽略的代价：压缩省下的 FLOPs 若因形状不佳而无法有效利用，实际时延改善会小于公式预测。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-19\">十九 · 从公式到验收口径</h3>\n<p>把上述推导固化为验收口径，需要三个可测量的量：其一，实测 TTFT 对 $\\rho$ 的斜率，与偏导式给出的常数比对，偏差大说明打分或合并引入了未计入的固定开销（同步点、核启动）；其二，KV 写入字节数随 $\\rho$ 的变化，验证带宽项是否按预期缩小；其三，压缩前后在目标任务上的精度差，特别是 OCR 与定位类样本，用来确认 $\\rho$ 的下界。三者共同决定服务配置里 $\\rho$ 的取值区间，而不是由单一吞吐指标拍板。一个具体判断：若实测斜率明显小于公式预测，说明瓶颈已转移到打分同步点或批内打包开销，此时继续降 $\\rho$ 无益，应转而优化融合核；若斜率明显大于预测，则检查窄 GEMM 的填充率与 KV 写入的对齐，这两处是公式未显式建模但实际会放大时延的地方。</p>\n<p>最后落在机制上：ViTCoP 的收益边界由 $N_{\\text{vis}}'$ 在三项中的线性系数共同划定，而 $\\rho^\\star$ 是 SLO、精度档位与批内异构三者联立的结果；任何把保留率当作静态超参的做法，都会在长文档或指令模糊的请求上把时延收益换成质量损失。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-20\">二十 · 一次性筛选的边界：打分退化、合并失真与保留率失配</h3>\n<p>该方案把全部压缩决策压在视觉编码器输出与 LLM 预填之间的一次性打分上，这决定了它的失效条件不是随机噪声，而是<strong>打分函数的判别力</strong>。相关性分数 $s_j=\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 只度量文本嵌入与单个视觉 token 表示的余弦相似度，不含任何跨 token 的上下文交互；当指令模糊（“看看这张图有什么问题”）或长文档场景中指令只覆盖图像局部区域时，分数分布趋于平坦，$\\mathcal{K}=\\mathrm{TopK}(\\{s_j\\},k)$ 的 top-$k$ 边界落在大量近似同分的 token 上，保留集合对扰动极其敏感——关键视觉 token 被误删不是概率事件，而是排序不稳定性的直接后果。更本质的是，$k$ 是外部给定的预算而非由分数分布自适应导出，方案本身没有机制在分数区分度低时自动抬高保留率，因此“指令明确”实际上是该方案正常工作的隐含前提，而非可选的优化条件。</p>\n<p>合并路径的代价可以写成一条失真上界：被合并的 token 集合 $\\mathcal{M}$ 中，任一 token 的位置信息在摘要表示中仅以邻域聚合形式残留，其空间坐标的可恢复性上界约为 $1/|\\mathcal{M}|$，即合并粒度越粗，细粒度定位越不可逆。这与 OCR、文档版面解析、指代定位类任务的需求正面冲突——这些任务恰恰依赖单 token 级的空间对应关系，而摘要 token 把多个 patch 压成一个向量后，解码阶段无法再拆回原坐标。工程上应把这类请求路由到不压缩的路径，或在同一服务栈内按任务类型设置保留率下限，而不是用统一 $k$ 覆盖全部流量。</p>\n<p>保留率失配是第三类失效，且方向与直觉相反：$k$ 过低时 KV cache 写入量按 $2N_{\\text{vis}}'d\\,B_{\\text{kv}}/\\mathrm{BW}$ 项下降，显存与带宽账面上很好看，但解码阶段可复用的上下文被削薄，模型倾向重复生成或答非所问，表现为输出长度膨胀、有效吞吐反而下降。因此调参不能只盯 TTFT，需以“TTFT 收益 / 输出 token 增量”作为联合指标。下表给出三类边界与对应工程处置：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机理</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>指令模糊 / 长文档</td><td>分数分布平坦，top-$k$ 排序不稳</td><td>关键 token 误删，答案质量塌陷</td><td>按分数方差自适应抬 $k$，或回退全量</td></tr><tr><td>OCR / 定位任务</td><td>邻域合并丢失坐标可恢复性</td><td>精度不可逆下降</td><td>任务级路由，禁用合并</td></tr><tr><td>$k$ 过低</td><td>解码上下文不足</td><td>输出变长，有效吞吐下降</td><td>联合优化 TTFT 与输出增量</td></tr></tbody></table>\n<p>与 DUET-VLM 的差别在此处显出工程含义：后者进入 LLM 浅层做二次注意力显著性压缩，能利用语言侧上下文修正视觉打分，代价是多一层前向；本方案的一次性筛选省掉这层开销，换来的正是上述对指令质量的强依赖。部署时应把打分模块视为一个带明确适用域的过滤器——指令明确、任务不依赖像素级定位时启用，其余流量走旁路，这比试图用统一保留率覆盖全部请求更稳。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-21\">二十一 · 请求形态：指令明确度决定保留率能否落地</h3>\n<p>ViTCoP 的负载配方第一条不是长度，而是<strong>指令形态</strong>。打分项 $s_j=\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 把文本指令嵌入当作查询向量，视觉 token 当作被检索的键；这套机制天然假设指令对图像内容有明确的指向性——“图中红色卡车左侧的箱子是什么颜色”这类查询，会把相关性分数拉出清晰的头部与长尾，TopK 的截断点落在分数陡降处，保留集合 $\\mathcal{K}$ 的语义边界与真实证据边界重合。反过来，“描述这张图”“这份文档讲了什么”这类宽泛指令，$\\mathbf{e}_t$ 几乎与所有视觉 token 等距，分数分布趋于平坦，TopK 退化为按索引或按位置截断，等于随机丢弃视觉证据。工程上应把指令明确度当作路由特征：对明确查询走低保留率，对宽泛指令走保守保留率甚至旁路压缩，而不是用一个全局保留率硬套所有流量。</p>\n<p>请求形态还决定压缩收益能否兑现。公式中预填时间的第一项 $\\frac{4N_{\\text{vis}}' d^2}{\\text{FLOPS}_{\\text{eff}}}$ 与第二项 $\\frac{2N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}$ 都正比于压缩后的视觉 token 数 $N_{\\text{vis}}'$，第三项 $\\frac{2N_{\\text{vis}}' d B_{\\text{kv}}}{\\text{BW}}$ 则把 KV 写入带宽一并压下来。当文本侧 $N_{\\text{txt}}$ 很短（单轮问答、短指令），第二项占比小，收益主要来自第一项与第三项；当文本很长（多轮对话历史、长指令模板），$N_{\\text{txt}}$ 抬高第二项权重，视觉 token 的边际削减价值反而更显著——但此时指令往往也更冗长模糊，打分区分度下降，两个效应相互抵消。这就是长文档场景下“削得动但削不准”的结构性矛盾。</p>\n<p>具体例子：同一张 1024×1024 商品图，ViT 切成上千个 patch token。查询“包装盒上的保质期印在哪”时，文本嵌入集中在包装文字区域，TopK 保留的 token 高度聚集，摘要 token 只覆盖背景；查询“这张图整体是什么风格”时，分数平坦，若仍按同一保留率截断，模型看到的只是图像一角，回答必然偏斜。前者是 ViTCoP 的理想负载，后者是它的失效负载。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-22\">二十二 · 长度分布：视觉 token 基数与文本 token 比例</h3>\n<p>负载配方的第二个维度是长度分布的形状，而不是平均值。视觉侧 $N_{\\text{vis}}$ 由分辨率与 patch 大小决定，是请求到达时就已知的确定量；文本侧 $N_{\\text{txt}}$ 随指令与历史浮动。决定压缩紧迫性的是比值 $N_{\\text{vis}}/N_{\\text{txt}}$：比值高（高分辨率图像 + 短指令）时，视觉 token 主导预填成本，压缩的边际收益最大；比值低（低分辨率缩略图 + 长对话）时，视觉 token 已不是瓶颈，压缩带来的 TTFT 改善被文本侧稀释，却仍要付出打分与合并的开销。</p>\n<p>打分本身不是免费的。跨模态相关性打分要在视觉 token 表示与文本嵌入之间做一次全量相似度计算，复杂度随 $N_{\\text{vis}}\\cdot d$ 增长；空间邻接合并还要按保留集合的邻接关系做聚合。这两步发生在 LLM 预填之前，属于串行前置开销，直接计入 TTFT。因此存在一个盈亏平衡点：压缩节省的预填时间必须大于打分与合并的时间。设保留率为 $r=k/N_{\\text{vis}}$，则节省量近似正比于 $(1-r)$ 的预填项，而前置开销近似与 $N_{\\text{vis}}$ 成正比、与 $r$ 无关。当 $N_{\\text{vis}}$ 很小（缩略图、低分辨率截图），前置开销可能吞掉全部收益，此时应直接旁路 ViTCoP。</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>把 $N_{\\text{vis}}'=rN_{\\text{vis}}$ 代入可见，TTFT 随保留率近似线性下降——这是该算法的核心卖点，也是负载配方的量化依据：保留率是唯一可以直接拨动的旋钮，长度分布决定拨动它的收益斜率。工程判断是：按 $N_{\\text{vis}}/N_{\\text{txt}}$ 分桶设保留率，高比值桶用激进保留率，低比值桶旁路或轻压缩，避免用统一保留率把两类流量都做坏。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-23\">二十三 · 并发与批大小：保留率如何改变批的构成</h3>\n<p>连续批处理下，批的构成不是请求数，而是 token 数。ViTCoP 压缩后每个请求进入 LLM 预填的视觉 token 数变为 $rN_{\\text{vis}}$，同一显存与算力预算下可容纳的并发请求数随之上升，批内 token 总数更接近文本侧主导的均衡形态。这带来两个连锁效应：其一，批内各请求的预填长度方差变小，调度器更容易把预填与解码交错排布，减少长预填请求阻塞解码步的情况；其二，KV cache 仅对保留 token 分配，单请求 KV 占用下降，KV 分页的碎片压力减轻，长上下文请求的准入更宽松。</p>\n<p>但批大小上升会反过来侵蚀压缩收益的稳定性。打分与合并是逐请求的前置阶段，批越大，前置阶段越容易成为流水线气泡：GPU 在等待一批请求全部完成打分合并后才能进入 LLM 预填，前置阶段的尾延迟被批内最慢请求拉长。若批内混有宽泛指令请求（分数平坦、合并摘要 token 多、打分后处理更重），它会拖慢整批。负载配方因此要求按指令形态做批内同质化，或把前置阶段与 LLM 预填做流水重叠，让已完成打分的请求先进入预填。</p>\n<p>具体代价可以定性描述：保留率降低使单请求 KV 写入量按比例减少，KV 带宽项 $\\frac{2N_{\\text{vis}}' dB_{\\text{kv}}}{\\text{BW}}$ 同步下降，解码阶段可复用的 KV 更小，显存腾出的空间转化为更高并发；但若保留率过低，解码阶段上下文不足，模型出现重复生成或答非所问，有效吞吐（按“可用回答”计）反而下降。吞吐与质量之间的这条曲线不是单调的，负载配方的任务就是找到拐点而非一味压低保留率。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-24\">二十四 · 负载不对时的三种失效形态</h3>\n<p>第一种失效是<strong>误删关键证据</strong>。指令模糊或长文档场景下，相关性打分区分度低，TopK 保留率无法自适应，分数接近的 token 被任意截断，真正承载答案的视觉 token 落入被合并的尾部。合并摘要 token 只保留粗粒度空间信息，模型拿到的是“某处有个类似文字的区域”，而不是具体字符，回答退化为泛泛而谈。这类失效在离线评测中表现为精度下降，在线上表现为用户追问率上升。</p>\n<p>第二种失效是<strong>细粒度任务精度塌陷</strong>。OCR 与定位类任务依赖 token 级位置信息，空间邻接合并把多个 patch 压成一个摘要向量，位置分辨率被稀释，字符边界与坐标回归失准。这类任务的负载特征是：文本指令短而精确（“读出第三行数字”），视觉 token 基数大，比值 $N_{\\text{vis}}/N_{\\text{txt}}$ 极高，恰好落在 ViTCoP 收益最大的区间，却也是它精度风险最大的区间。负载配方必须把任务类型作为硬约束：OCR、 grounding、计数类请求直接旁路压缩，不参与保留率调优。</p>\n<p>第三种失效是<strong>保留率过低引发的解码退化</strong>。KV cache 虽随保留率减小，但解码阶段可复用的视觉上下文不足，模型在生成中途失去视觉锚点，出现重复短语、答非所问或提前终止。这不是预填阶段的延迟问题，而是解码阶段的质量问题，监控上表现为输出长度分布异常与重复 n-gram 比例上升。工程上应把保留率下限与任务类型绑定，并对解码输出做轻量重复检测，触发时回退到更高保留率重跑。</p>\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>保留率取向</th><th>主要风险</th><th>系统代价表现</th></tr></thead><tbody><tr><td>指令明确、短文本、高分辨率</td><td>激进低保留率</td><td>误删边缘证据</td><td>TTFT 显著下降，KV 占用下降</td></tr><tr><td>指令宽泛、长文档</td><td>保守高保留率或旁路</td><td>分数平坦、截断任意</td><td>前置打分开销占比上升</td></tr><tr><td>OCR/定位/计数</td><td>旁路</td><td>位置分辨率损失</td><td>无预填收益，精度优先</td></tr><tr><td>缩略图、低分辨率</td><td>旁路</td><td>前置开销吞收益</td><td>打分合并时间超过节省时间</td></tr></tbody></table>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-25\">二十五 · 配方落地：把保留率做成按桶可调的运行时参数</h3>\n<p>负载配方的工程形态是一张路由表，而不是一个常数。入口处解析请求的三个特征：任务类型（是否 OCR/定位）、指令明确度（可用指令长度、疑问词密度、是否含指代对象做粗判）、长度比值 $N_{\\text{vis}}/N_{\\text{txt}}$。三者共同决定该请求走哪一档保留率，或直接旁路。保留率档位与 SLO 挂钩：TTFT 敏感的低延迟档用低保留率，质量敏感档用高保留率，两档共享同一套打分与合并实现，只是 $k$ 不同。</p>\n<p>运行时还需要一个反馈回路。由于打分区分度无法在请求到达时精确预知，可在打分后检查分数分布的陡峭程度——头部与尾部的分差、TopK 边界处的分数落差——作为保留率是否可信的代理指标。落差大则按计划截断，落差小则自动抬升 $k$ 或退回不压缩路径。这一步只增加一次轻量的分数统计，不引入额外模型，符合训练无关、推理侧插件的定位。</p>\n<p>容量规划上，ViTCoP 改变的是预填阶段的 token 预算与 KV 分配，不改变并行拓扑与阶段划分——这一点与跨阶段并行服务不同，后者动的是阶段并行结构。因此容量模型可以沿用原有预填/解码配比，只把视觉 token 数替换为 $rN_{\\text{vis}}$ 后重算 TTFT 与 KV 占用，再按任务桶加权得到混合负载下的有效保留率。混合负载的有效吞吐取决于各桶流量占比：明确指令流量占比越高，整体收益越接近线性下降的乐观估计；宽泛指令与 OCR 流量占比越高，收益越被旁路请求稀释。配方设计的实质，就是承认并非所有流量都该被压缩，并把不该压缩的那部分干净地挡在压缩路径之外。</p>\n<p>最后落在具体机制上：打分后分数分布的陡峭度检查应作为保留率自适应唯一入口，它与 $s_j=\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$、$\\mathcal{K}=\\mathrm{TopK}(\\{s_j\\},k)$ 共用同一次前向，不增加额外模型调用；陡峭度低于阈值即抬升 $k$ 或旁路，高于阈值才执行空间邻接合并。这条判断把负载配方的质量风险收敛到一次分数统计上，而不是散落在调度器与业务层的经验规则里。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-26\">二十六 · 负载配方与失效边界：什么时候该关掉协同筛选</h3>\n<p>协同预填的收益不是无条件成立的，它本质上是把「视觉 token 预算」当成一个可调旋钮，而这个旋钮的合理取值由请求形态决定。设保留率为 $\\rho=k/N_{\\text{vis}}$，则预填代价近似按 $\\rho$ 缩放：<div class=\"formula\">$$T_{\\text{prefill}}(\\rho)\\approx \\rho\\cdot\\frac{4N_{\\text{vis}}d^2+2N_{\\text{vis}}N_{\\text{txt}}d}{\\text{FLOPS}_{\\text{eff}}}+\\rho\\cdot\\frac{2N_{\\text{vis}}d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>这说明 TTFT 随保留率近似线性下降，但同时 KV cache 占用也线性缩小——收益是双份的，代价也是双份的：$\\rho$ 一旦压过头，解码阶段可复用的上下文就变薄。负载配方的核心判断因此不是「压不压」，而是「每个请求的 $\\rho$ 该由谁定」。</p>\n<p>适配的请求形态有三类特征：单图或少量图、指令明确（「这张图里的红色阀门在哪」「读出表格第二行」）、文本侧较短。这类请求里 $\\mathbf{e}_t$ 语义集中，$s_j=\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 的分数分布区分度高，TopK 截断能干净地切出相关 patch，$\\rho$ 可以压到很低而精度不掉。批大小上，该方案对连续批处理是友好的：压缩发生在进入 LLM 之前，同一 batch 内不同请求的视觉 token 数不再被最长请求拖平，调度器按压缩后的实际长度装箱，批内 token 方差下降，padding 浪费减少。反过来，多图长文档、指令含糊（「总结一下这份材料」）、需要跨图比对的请求，分数分布接近平坦，TopK 等于随机采样，此时应把 $\\rho$ 抬到接近 1 或直接旁路该插件。</p>\n<p>负载不对时的失效是分层的，不是单一的精度下降。<table class=\"mini\"><thead><tr><th>错配形态</th><th>机制后果</th><th>系统代价</th></tr></thead><tbody><tr><td>指令模糊、长文档</td><td>打分区分度低，关键 token 被误删</td><td>TTFT 降了但答案错，重试率上升，等效吞吐反降</td></tr><tr><td>OCR / 定位类任务</td><td>邻接合并摘要丢失细粒度位置</td><td>精度明显下降，且无法靠增大 $k$ 完全恢复</td></tr><tr><td>$\\rho$ 设置过低</td><td>解码上下文不足</td><td>KV 省了，但重复生成、答非所问，输出 token 数膨胀</td></tr></tbody></table>第三行尤其值得警惕：它把预填省下的时间在解码阶段又吐了回去，端到端时延可能不降反升——只盯 TTFT 的容量规划会在这里翻车。</p>\n<p>工程判断落在准入控制上：在网关侧按请求特征（图数、指令长度、任务类型标签）决定是否启用插件与 $\\rho$ 档位，把 OCR、定位、多图长文档请求路由到未压缩路径，其余走压缩路径；同时对 $\\rho$ 设下限，保证解码侧最小上下文。这套逻辑训练无关、可作为推理侧插件接入，集成风险低，但它的边界必须写进 SLO：协同预填优化的是「指令明确的单图查询」这一类负载的 TTFT 与显存，而不是通用 VLM 预填的万能加速器。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-27\">二十七 · 硬件档位：按保留率与 SLO 反推 SM 与带宽配比</h3>\n<p>ViTCoP 的部署配方不是从“买什么卡”开始，而是从“保留率 k/N 落在哪个区间”开始。预填公式里两项性质完全不同：第一项是算力项，正比于保留视觉 token 数 N′ 与 d²、N′·N_txt·d；第二项是 KV 写入带宽项，正比于 N′·d·B_kv。当保留率压到很低时，第一项被砍得最狠，第二项相对占比上升，此时瓶颈从 tensor core 的 FLOPS_eff 滑向 HBM 带宽与 KV 写入。工程判断因此是：高保留率（接近全量）请求应落在算力富余、单卡 FLOPS_eff 高的档位（如 B200 单机、SM100 满配 tcgen05 MMA）；低保留率请求则对算力不敏感，反而对 KV 分配与显存写带宽敏感，适合放在显存带宽与容量更宽裕的 GB200 NVL72 机柜内做大批量聚合。同一集群里两种档位混跑时，调度器必须按“保留率分档”而不是按“图像分辨率分档”路由，否则高保留率请求会被塞进带宽档位、低保留率请求会占着算力档位空转。</p>\n<p>打分阶段本身是独立的一段开销：文本嵌入与视觉 token 的余弦相似度是 N_vis·d 级别的乘加，量级远小于预填主项，但它发生在预填之前，属于串行关键路径。若打分放在 CPU 或独立小卡上，会引入一次额外的 H2D/D2H 往返；放在与 LLM 同卡的 SM 上则与后续预填共享同一份权重驻留，代价是打分核与预填核之间的 launch 间隙。可复现的配置思路是把打分核与 ViT 编码尾段放在同一 stream，用一次 kernel fusion 把 s_j 计算与 top-k 的选择合并，避免中间分数张量落回 HBM——这一步省下的是 N_vis·d 的写带宽，在低保留率档位上恰好是第二项的主要竞争者。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-28\">二十八 · 并行拓扑：TP 沿 d 切、视觉侧不跨 stage</h3>\n<p>预填算力项里 d² 出现在 4N′d² 上，意味着张量并行沿隐藏维切分对第一项收益最直接；而 2N′N_txt d 这一交叉项在 TP 切分后需要在注意力和 MLP 之间做 all-reduce，通信量与 N′·N_txt 成正比，保留率越低这一项越小，TP 的通信代价也随之下降。因此拓扑配方是：TP 度按“最高保留率档位的算力需求”定，而不是按平均保留率定；低保留率请求复用同一 TP 组不会浪费通信，因为它们的交叉项本来就小。视觉编码器一侧不做 PP 切分——ViT 的 patch 序列在压缩前是连续的，跨 stage 切分会把打分所需的完整视觉 token 序列打断，逼出一次中间张量的跨卡搬运，得不偿失。</p>\n<p>对 GB200 NVL72 这类机柜级域，可复现的做法是把一个 TP 组限制在单机 8 卡内（NVLink 5 域内全互联），把跨机通信留给 DP 副本与 KV 传输。理由是 ViTCoP 削减的是单请求内的预填量，不改变副本间的负载均衡形态；把 TP 拉到跨机只会让 all-reduce 走更贵的链路，而保留率下降后 all-reduce 消息本就变小，跨机的固定延迟占比反而上升。解码阶段复用保留 token 的 KV，KV 页的分布是稀疏且不规则的，PD 分离场景下这类 KV 的传输更适合走 NIXL 的点对点路径而非集合通信。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-29\">二十九 · 量化方案：打分保精度、预填吃低精度</h3>\n<p>量化配方要按“哪一段对数值误差敏感”分层。相关性打分输出的是排序，top-k 的选择对分数绝对值的微小扰动不敏感，但对分数间的相对次序敏感；因此打分用的文本嵌入与视觉 token 表示应保持较高精度（FP8 甚至 BF16），避免低精度下近邻分数并列导致 top-k 抖动、保留集合在请求间不稳定。相反，压缩后的视觉 token 进入 LLM 预填时，参与的是 4N′d² 与交叉项的大规模矩阵乘，这部分正是 NVFP4/FP8 与 tcgen05 MMA 的收益区：N′ 已被压小，单次预填的矩阵规模下降，低精度带来的吞吐提升直接转化为 TTFT 下降，而精度损失被“只保留相关 token”这一筛选部分对冲——被丢弃的本就是低相关 token，其量化误差不会进入上下文。</p>\n<p>代价要写清楚：把预填切到 NVFP4 后，KV cache 的写入量按 B_kv 计并未减少（KV 的元素数由保留 token 数与层数决定），所以低精度省的是算力项而非带宽项；若同时把 KV 也量化为 FP8，则第二项的 B_kv 减半，这才是低保留率档位真正的带宽收益。工程判断是：算力档位用 NVFP4 预填 + FP8 KV，带宽档位用 FP8 预填 + FP8 KV，打分统一保 BF16/FP8。合并摘要 token 是空间邻接聚合的结果，其数值是多个 token 的加权组合，量化时应对摘要 token 单独用较高精度，否则 OCR/定位类任务的空间信息会先被合并稀释、再被量化二次稀释。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-30\">三十 · KV 策略：只为保留 token 分配，按页粒度回收</h3>\n<p>机制上 KV cache 仅对保留 token 分配并在解码阶段复用，这带来一个非标准的分配形态：同一请求内 KV 序列长度是 N′+N_txt，而 N′ 随指令变化，导致页表在请求间长度不一。可复现的配置是把 KV 池按固定页大小管理，保留 token 的 KV 在预填时按 top-k 集合的顺序紧凑写入，摘要 token 的 KV 紧随其后；被丢弃 token 不占页，页分配器因此看到的是“短请求”，显存占用随保留率近似线性下降。调度参数上，连续批处理的最大批大小应按“最坏保留率下的 KV 峰值”设上限，否则一个高保留率请求会把整批的 KV 预算吃满，逼出抢占与重算。</p>\n<p>失败模式在这里有直接的调度含义：保留率过低时 KV 虽小，但解码上下文不足会导致重复生成或答非所问，表现为解码步数变长、有效吞吐反而下降。配方上应给保留率设下限，并在调度器里把“解码步数超阈值”的请求标记为保留率不足，回退到更高保留率重跑预填——这是一次显式的重算代价，换来的是避免长尾解码把批吞吐拖垮。另一个参数是摘要 token 的数量上限：它决定 KV 的最小占用，也决定细粒度信息的保留下限，OCR/定位类请求应走独立队列并禁用合并摘要。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-31\">三十一 · 调度参数与可复现配置思路</h3>\n<p>把上述四层拼成一个可复现的配置流程：第一步，按业务请求的指令明确度分队列——明确查询走高压缩档，长文档/模糊指令走保守档，OCR/定位走不压缩档；第二步，为每档标定保留率 k/N 与摘要 token 上限，用预填公式估算 TTFT 的两项占比，判断该档落在算力敏感区还是带宽敏感区；第三步，按档位绑定硬件档位与量化组合（算力档：B200 单机 TP8、NVFP4 预填、FP8 KV、BF16 打分；带宽档：NVL72 机柜内聚合、FP8 预填、FP8 KV、按页紧凑分配）；第四步，设连续批处理的最大批大小与 KV 峰值上限，给解码步数设告警阈值以触发保留率回退。</p>\n<p>调度器需要的一个关键量是“保留率预算”：对每个请求，k 由指令长度与图像 token 数共同决定，但打分区分度在模糊指令下会下降，top-k 的分数分布变得平坦。可复现的判据是看 top-k 边界处的分数间隔——间隔小于阈值即判定区分度不足，自动上调 k 或转保守档。这一步把失败模式里的“保留率无法自适应”变成了一个可观测的调度信号，而不是靠离线调参。伪代码思路是：<ul><li>计算 s_j 与排序；</li><li>取第 k 与第 k+1 名的分数差 Δ；</li><li>若 Δ 低于阈值，k ← min(2k, N_vis) 重排；</li><li>否则按 K 分配 KV 页并进入预填。</li></ul>代价是重排带来的额外打分开销，但打分项量级远小于预填主项，在算力档位上可忽略，在带宽档位上则需与 KV 写带宽争抢，故阈值应设得偏保守。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-32\">三十二 · 与相邻方案的部署边界</h3>\n<p>部署配方必须明确 ViTCoP 不做什么：它只在视觉编码器输出与 LLM 预填之间做一次性筛选与合并，不进入 LLM 浅层做二次注意力显著性压缩（那是 DUET-VLM 的路径），也不改变阶段并行拓扑（那是跨阶段并行服务的路径）。因此在本配方里，PD 分离的预填池与解码池划分不受 ViTCoP 影响，变的只是预填池内单请求的算力与 KV 占用；分离式部署的容量规划应按压缩后的预填负载重算预填池规模，而解码池规模由保留 token 的 KV 与解码步数决定。若把 ViTCoP 与多模态全静态量化叠加，需注意两者都作用于预填算力项，收益不独立可加，应按“先压缩后量化”的顺序标定，避免在低保留率下重复计算同一份算力节省。</p>\n<p>最后的工程判断落在保留率与硬件档位的耦合上：保留率是唯一同时进入算力项与带宽项的变量，也是唯一能在请求级动态调整的变量；硬件档位与量化组合是静态配置，调度参数是动态旋钮。可复现的配方因此把静态配置按“最高保留率档位”定容、把动态旋钮按“分数间隔 + 解码步数”闭环，让压缩率成为调度信号而非离线常数——这才是 ViTCoP 作为训练无关推理插件在 Blackwell 服务栈里能稳定落地的方式。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-33\">三十三 · 保留率不是旋钮，是契约：失效边界与代价核算</h3>\n<p>这套配方最容易踩的坑，是把保留率当成一个可以随时下调的吞吐旋钮。实际上它是插件与下游 LLM 之间的契约：$\\mathcal{K}=\\mathrm{TopK}(\\{s_j\\},k)$ 一旦生效，KV cache 只对 $\\mathcal{K}$ 分配，解码阶段再也拿不回被丢弃的视觉证据。因此部署时必须先划出不可压缩任务的硬边界——OCR、表格字段抽取、坐标定位、密集小字阅读，这些任务的答案依赖被合并摘要 token 抹掉的细粒度空间关系，保留率压得越低，精度塌陷越陡。工程判断是：按请求类型做静态路由，检测到上述意图（关键词、任务标签或上游分类器）就直接旁路压缩路径，走原始 token 预算，宁可牺牲这一路 TTFT 也不让精度失守。</p>\n<p>失效条件集中在打分区分度上。指令模糊（“看看这张图有什么问题”）或长文档多页输入时，$\\mathbf{e}_t$ 与各 $\\mathbf{v}_j$ 的余弦分布趋于平坦，TopK 的截断点落在噪声区，关键 token 被误删且系统无从感知。可复现的防护思路是给打分加一道自适应闸门：先算分数分布的归一化熵 $H=-\\sum_j p_j\\log p_j$（$p_j$ 为 softmax 后的相关性权重），熵高于阈值即判定指令信息量不足，自动抬高 $k$ 或退回全量预填；同时对保留集合做空间覆盖率检查，若被保留 token 在 patch 网格上的覆盖过于集中，补回邻接摘要 token。这套闸门本身是纯推理侧逻辑，不引入训练依赖。</p>\n<p>代价要按公式拆开看。压缩直接削减的是第一项 $4N_{\\text{vis}}' d^2+2N_{\\text{vis}}'N_{\\text{txt}}d$ 与 KV 写入项 $2N_{\\text{vis}}'d\\,B_{\\text{kv}}/\\mathrm{BW}$，TTFT 随保留率近似线性下降；但打分与合并本身要付一次跨模态相似度计算的固定开销，且这部分开销与图像分辨率成正比、与保留率无关，因此保留率越低，摊销在每 token 上的相对成本越高——存在一个收益拐点，低于它继续压缩只是把算力从预填搬到打分。下表给出配置决策的定性对照：</p>\n<table class=\"mini\"><thead><tr><th>请求形态</th><th>保留策略</th><th>主要代价</th><th>风险</th></tr></thead><tbody><tr><td>指令明确的单图问答</td><td>低保留率 + 摘要合并</td><td>打分固定开销占比上升</td><td>低</td></tr><tr><td>长文档多页</td><td>熵闸门抬高 $k$</td><td>TTFT 收益收窄</td><td>中，需覆盖率校验</td></tr><tr><td>OCR/定位</td><td>旁路压缩</td><td>无 TTFT 收益</td><td>精度优先</td></tr></tbody></table>\n<p>最后一条边界常被忽略：保留率过低时 KV cache 确实变小、显存压力缓解，但解码阶段上下文不足会诱发重复生成与答非所问，表现为输出长度异常增长——这时的系统代价从预填延迟转移到了解码吞吐上，端到端反而更差。因此调度参数里必须把“最小保留 token 数”与“解码最大新 token 数”绑定成一组约束，用解码侧的重复率监控反向触发保留率上调，而不是让压缩率单独最优化。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-34\">三十四 · 预填时延的四项分解与“谁在付钱”</h3>\n<p>ViTCoP 的系统收益必须放回预填时延公式里看，因为它的机制只作用于公式中的两个变量：进入 LLM 的视觉 token 数 $N_{\\text{vis}}'$，以及随之写入的 KV 字节数。公式本身把代价拆成四项，前两项是算力项，后两项是带宽项：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>第一项 $4N_{\\text{vis}}' d^2$ 是视觉 token 过 QKV 与输出投影的权重侧算力，与文本长度无关，只随保留率和隐藏维 $d$ 走；第二项 $2N_{\\text{vis}}' N_{\\text{txt}} d$ 是视觉 token 与文本 token 之间的注意力交互，随文本长度线性增长。这两项的分界点决定压缩收益落在哪：指令短、图像 token 多时，第一项占主导，削减 $N_{\\text{vis}}'$ 直接砍掉大部分 FLOPs；长文档、长指令场景下第二项抬头，同样的保留率带来的相对收益被稀释。后两项是 KV 写入的带宽代价，$B_{\\text{kv}}$ 是每 token 每层的 KV 字节数，在 FP8 KV 下比 BF16 减半，但结构不变——KV 只对保留 token 分配，所以这一项与 $N_{\\text{vis}}'$ 严格成正比。工程判断是：ViTCoP 的收益上限由第一项与第三项共同封顶，而第二项是它无法触及的部分，这也是它在长指令负载下边际收益递减的根源。</p>\n<p>具体例子：一个 $d=4096$、$N_{\\text{txt}}=512$ 的请求，若原始视觉 token 为 4096、保留率压到 1/4，则第一项从 $4\\times4096\\times4096^2$ 降到四分之一，第二项同样降到四分之一，两项同时受益；但若 $N_{\\text{txt}}$ 涨到 8192，第二项在压缩前的绝对值已远超第一项，压缩后剩余的第二项仍是主导项，此时继续压低保留率的收益远不如缩短文本侧上下文。这解释了为什么该机制在“指令明确的查询”上收益最显著——那正是第一项主导的区间。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-35\">三十五 · 显存与 KV cache：压缩比不等于显存节省比</h3>\n<p>KV cache 的分配粒度是保留 token 集合 $\\mathcal{K}$，因此显存占用近似为 $2\\,|\\mathcal{K}|\\,d\\,L\\,b_{\\text{kv}}$（$L$ 为层数，$b_{\\text{kv}}$ 为每元素字节数，系数 2 指 K 与 V）。看起来压缩比直接映射为显存节省比，实际不是。原因有三：其一，ViT 编码器自身的激活与中间特征在打分阶段仍需驻留，打分需要文本嵌入 $\\mathbf{e}_t$ 与全部视觉 token 表示 $\\mathbf{v}_j$ 同时在场，这意味着在筛选完成前，峰值显存仍按未压缩的 $N_{\\text{vis}}$ 计；其二，合并摘要 token 需要额外的空间邻接索引结构，虽然量小但在大批量下累积；其三，连续批处理下不同请求的保留率不同，KV 块分配器面对的是变长序列，碎片化会吃掉一部分理论节省。</p>\n<p>打分步骤本身可写成一次余弦相似度批量计算：</p>\n<div class=\"formula\">$$s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j),\\quad \\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$$</div>\n<p>这个计算的代价是 $O(N_{\\text{vis}} d)$ 的乘加与一次全序列的 top-k 归约。归约在长视觉序列上是带宽受限的：需要把 $N_{\\text{vis}}$ 个分数写回并扫描，若 $N_{\\text{vis}}$ 达到数万量级，这一步的显存往返会形成一个新的、位于 ViT 与 LLM 之间的串行段，它不在原公式里，却是实际 TTFT 的组成部分。工程上的处理是把打分与 ViT 最后一层的输出融合，避免把完整视觉 token 序列物化到 HBM 再读回；否则压缩省下的 KV 带宽会被打分阶段的额外往返抵消一部分。代价定性表述：保留率越低，KV 显存与写入带宽越省，但打分阶段的固定开销占比越高，存在一个收益饱和点。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-36\">三十六 · 带宽与通信：压缩改变了集合通信的消息尺寸</h3>\n<p>在张量并行下，预填阶段的每次 all-reduce 或 all-gather 消息尺寸与序列长度成正比。ViTCoP 压缩后，视觉段的消息从 $N_{\\text{vis}}$ 降到 $N_{\\text{vis}}'$，通信量随之下降，但下降不是线性的：文本段的 token 未压缩，通信消息由“视觉段 + 文本段”拼接而成，当文本段占比上升时，整体消息尺寸的缩减比例被摊薄。更关键的是通信次数不变——压缩减少的是每次消息的字节数，不是集合通信的调用次数，因此在小消息、高频率的拓扑上，延迟项（与消息尺寸弱相关）不会改善，只有带宽项改善。NVLink 5 的高带宽让带宽项在单节点内通常不是瓶颈，跨节点场景下这一项的权重才上升。</p>\n<p>分离式预填/解码部署里，压缩后的 KV 需要从预填节点传到解码节点，传输量正比于 $|\\mathcal{K}|$。这是 ViTCoP 在分离式架构中的额外价值：它同时削减了预填算力和 KV 传输字节，而纯算力侧的优化只削减前者。代价是传输的消息更小、更碎，NIXL 这类传输层在小消息上的有效带宽利用率低于大消息，需要按请求聚合后再传，否则单位字节的传输开销上升。具体例子：一个批内 8 个请求、每个请求视觉段从 4096 token 压到 1024 token，若逐请求传输，每次传输的消息尺寸缩小到四分之一，但传输次数不变，聚合传输能把小消息合并成一次大传输，恢复带宽效率。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-37\">三十七 · 功耗：算力节省与固定开销的抵消</h3>\n<p>预填阶段的功耗主要由 MMA 阵列的利用率和 HBM 访问构成。ViTCoP 削减 FLOPs 直接降低 MMA 活跃周期，但打分步骤引入了一段以逐元素乘加与归约为主的低利用率计算，这段计算的功耗密度低于 MMA 密集段，却延长了总活跃时间。净效果取决于压缩比与打分开销的比值：保留率压得足够低时，省下的 MMA 周期占主导，功耗下降；保留率接近 1 时，打分开销纯粹是额外负担，功耗反而略升。这就是该机制必须配合保留率策略的原因——它不是一个“免费”的插件，保留率的选择直接决定功耗是正收益还是负收益。</p>\n<p>另一个功耗维度是 KV cache 的驻留。KV 占用下降意味着同样显存下可以容纳更多并发请求，单位功耗的有效吞吐上升；但若为了填满释放出的显存而提高批大小，MMA 与 HBM 的活跃度回升，单请求功耗下降被批大小的上升抵消，系统总功耗可能不降。工程判断是：ViTCoP 的功耗收益应折算为“每 token 的能耗”，而不是整机功耗，后者由批调度策略主导。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-38\">三十八 · 尾延迟：保留率自适应失败是长尾的主因</h3>\n<p>平均 TTFT 随保留率近似线性下降，但尾延迟（P99）的行为不同。ViTCoP 的保留率是全局一次性决策，不随请求内容自适应，因此当文本指令模糊或长文档场景下相关性打分区分度低时，top-$k$ 选出的 token 可能集中在少数区域，摘要 token 承载了剩余信息，进入 LLM 后模型需要更长的解码步数才能收敛——这表现为解码阶段尾延迟拉长，而非预填阶段。也就是说，压缩把延迟从预填段转移到了解码段，平均 TTFT 改善，但端到端尾延迟未必改善。</p>\n<p>失败模式的连锁是：保留率过低 → KV cache 减小但上下文不足 → 解码阶段重复生成或答非所问 → 需要更多解码步或触发重试 → 尾延迟恶化。在连续批处理下，一个长尾请求会占住 KV 块并阻塞后续请求的准入，尾延迟因此具有传染性。缓解手段是在打分阶段引入区分度指标（分数分布的熵或 top-k 与次优的间隔），区分度低于阈值时抬高保留率，用算力换稳定性；这把一次性决策变成带反馈的决策，代价是打分阶段多一次统计归约。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-39\">三十九 · 规模上去以后哪里先崩</h3>\n<p>按代价项的缩放行为排序，最先崩的是打分阶段的显存峰值与串行段。$N_{\\text{vis}}$ 随图像分辨率与 patch 数增长，打分需要全序列在场，峰值显存按未压缩计，因此当单请求视觉 token 数逼近显存预算时，压缩带来的 KV 节省无法兑现为并发提升，因为峰值卡在筛选前。第二个崩点是 top-k 归约的带宽：全序列分数写回与扫描是 $O(N_{\\text{vis}})$ 的 HBM 往返，在数万 token 量级上形成可观测的固定延迟，且不随保留率下降而缩小。第三个崩点是精度侧而非性能侧——OCR 与定位类任务在合并摘要 token 后细粒度空间信息丢失，规模越大、图像越密，误删的关键 token 越多，这类请求的尾延迟与错误率同时上升。</p>\n<p>相对晚崩的是集合通信与 KV 传输：这两项与 $N_{\\text{vis}}'$ 成正比，压缩直接受益，且 NVLink 5 的高带宽给了较大余量。最后崩的是 MMA 算力项，因为它随 $d^2$ 增长而与文本长度无关，压缩后仍是最大单项，只有在 $d$ 很大且保留率极低时才让出主导地位。工程上的容量规划应按“峰值显存 → 归约带宽 → 精度失败率”的顺序设限，而不是按平均 TTFT 设限；前者决定系统能否扩容，后者只决定单请求体验。具体机制上的落点是：把打分与 ViT 末层融合以削掉峰值物化，把 top-k 改为分块流式归约以削掉全序列往返，把区分度阈值作为保留率的自适应闸门以削掉精度长尾——这三项都不改变算法语义，只改变它在规模上的崩溃顺序。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-40\">四十 · 规模上去以后，先崩的是打分与合并的串行段</h3>\n<p>把保留率记作 ρ=k/N_vis，预填时间近似为 T_prefill≈(4ρN_vis d²+2ρN_vis N_txt d)/FLOPS_eff+2ρN_vis d B_kv/BW。这条式子说明两件事：TTFT 随 ρ 近似线性下降，但斜率里同时含算力项与 KV 写入带宽项，因此当 ρ 已经压到很低、算力项不再主导时，继续下调 ρ 的边际收益会被打分环节本身吃掉。打分与合并发生在 ViT 输出与 LLM 预填之间，是一段无法与主预填流水重叠的串行工作：它要对每个视觉 token 与文本嵌入做一次余弦相似度，代价约为 N_vis·d 次乘加，再对 N_vis 个分数做 TopK 选择。单请求下这段开销相对整个预填可忽略，但在连续批处理下它成为批内所有请求的共同前置屏障——批越大，屏障越宽，GPU 在打分结束前无法启动任何一条请求的 LLM 预填，SM 占用出现周期性空窗。</p>\n<p>规模上升后第二个崩点是通信与显存的不对称。ViT 侧通常按图像并行切分，视觉 token 在编码完成后需要汇聚到执行打分的 rank 上，汇聚量正比于 N_vis·d·(并行度−1)；而压缩后真正进入 LLM 预填的 token 只有 ρN_vis，于是出现“跨卡搬运全量视觉 token、只用其中一小部分”的带宽浪费。在 NVL72 这类域内高带宽拓扑上这笔开销尚可被 NVLink 5 吸收，一旦视觉编码器与 LLM 预填分处不同节点、走的是 scale-out 网络，汇聚段就会从微秒级升到毫秒级，直接体现在 TTFT 的尾部分布上。KV cache 侧虽然只对保留 token 分配，显存收益是实打实的 ρ 倍缩减，但打分所需的视觉 token 全量表示必须驻留到选择完成，峰值显存并不随 ρ 下降而同比例下降。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先饱和的资源</th><th>表现</th></tr></thead><tbody><tr><td>批大小增大</td><td>打分串行段</td><td>批内屏障变宽，SM 空窗，吞吐增速低于线性</td></tr><tr><td>视觉并行度增大</td><td>汇聚带宽</td><td>跨节点时延进入 TTFT 尾部</td></tr><tr><td>ρ 继续下调</td><td>解码上下文</td><td>KV 变小但重复生成、答非所问增多</td></tr><tr><td>长文档/模糊指令</td><td>打分区分度</td><td>TopK 无法自适应，关键 token 被误删</td></tr></tbody></table>\n<p>尾延迟的来源因此不是单一环节，而是三个耦合项：打分屏障在批内的排队、汇聚段在网络拥塞时的抖动、以及 ρ 过低引发的解码期重试。工程判断上，ρ 不应作为全局常数下发，而应按指令明确度分档——明确查询走低 ρ，长文档与 OCR/定位类请求强制走高 ρ 甚至旁路压缩路径；同时把打分与合并放到独立的轻量 kernel 或独立 stream 上，使其与上一批的解码阶段重叠，把串行屏障摊薄。功耗维度上，压缩带来的收益主要体现在预填阶段的张量核心占用时间缩短，而打分段本身是访存密集型、功耗密度低，整卡功耗曲线会从“预填高峰+解码低谷”变为更平坦但更长的中段平台，这对机柜级供电与散热的容量规划提出了与纯算力削减不同的假设。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-41\">四十一 · 精度失效的三条路径与可观测信号</h3>\n<p>ViTCoP 的精度问题不是随机噪声，而是沿打分链路逐级放大的确定性失效。第一条路径是<strong>打分区分度塌缩</strong>：指令模糊或长文档场景下，文本嵌入 $\\mathbf{e}_t$ 与视觉 token 表示 $\\mathbf{v}_j$ 的余弦分数分布趋于平坦，$\\mathrm{TopK}(\\{s_j\\},k)$ 的截断边界落在大量近似等值的分数之间，此时 top-$k$ 集合对微小扰动极度敏感，保留的 token 集合在不同请求间漂移。第二条路径是<strong>合并摘要的信息坍缩</strong>：空间邻接合并把 $N_{\\text{vis}}-k$ 个 token 压成少量摘要 token，位置编码被平均化，OCR 与定位任务所需的细粒度空间关系不可恢复。第三条路径是<strong>保留率过低导致的解码退化</strong>：KV cache 只对保留 token 分配，解码阶段上下文不足，模型倾向重复生成或答非所问，这类错误在预填阶段不可见，只在生成输出上暴露。</p>\n<p>三条路径对应三类可观测信号，监控必须分层采集而非只看端到端指标。打分层采集分数分布的统计量——分数均值、方差、top-$k$ 边界处的分数间隔（gap），gap 收缩到接近零即判定区分度塌缩。压缩层采集实际保留率 $k/N_{\\text{vis}}$ 与摘要 token 数量，与请求画像中的预期预算比对。输出层采集生成文本的重复 n-gram 比例、答案与图像区域的对齐率（用轻量定位探针请求周期性抽样）。工程上把这三层信号绑定到同一 trace id，才能在尾延迟尖刺出现时区分是压缩过度还是批调度问题。</p>\n<p>代价上，打分统计量的采集几乎零开销（分数向量本就在寄存器与共享内存中），但定位探针请求需要真实跑完整解码，按抽样比例消耗吞吐；若按 1% 抽样，探针开销与主流量成正比，在 SLO 紧张的集群上应把探针调度到低优先级队列。具体例子：文档扫描类请求中，指令为“提取表格中的金额”，分数 gap 若在多个请求上持续低于阈值，说明该批请求的视觉 token 与文本语义相关性普遍偏弱，此时应触发保留率上调而非继续压预算。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-42\">四十二 · OOM 的两种来源：预算漂移与 KV 峰值叠加</h3>\n<p>ViTCoP 的显存账本由保留 token 决定，但 OOM 往往不是保留率设错，而是<strong>预算漂移</strong>：请求画像按平均图像尺寸估算 $N_{\\text{vis}}$，实际请求中高分辨率图像使 $N_{\\text{vis}}$ 远超预期，压缩后仍超出预算。第二种来源是<strong>KV 峰值叠加</strong>：连续批处理下，新请求的预填 KV 写入与在途解码请求的 KV 增长在同一时刻叠加，压缩后的视觉 KV 虽小，但文本 KV 与解码增量不受 ViTCoP 控制，峰值出现在批内请求数最多、序列最长的时刻。</p>\n<div class=\"formula\">$$M_{\\text{kv}} \\approx 2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}} + 2\\,N_{\\text{txt}} d\\,B_{\\text{kv}} + \\sum_{i \\in \\text{batch}} 2\\,L_i d\\,B_{\\text{kv}}$$</div>\n<p>式中 $N_{\\text{vis}}'$ 为压缩后视觉 token 数，$L_i$ 为第 $i$ 个在途解码请求的已生成长度。诊断要点是把 OOM 发生时刻的批组成快照下来：若 OOM 集中在图像尺寸分位数的高端，属于预算漂移，解法是在 tokenize 阶段按实际 patch 数重算预算并拒绝超限请求或降采样；若 OOM 与图像尺寸无关而与批内解码请求数强相关，属于 KV 峰值叠加，解法是给预填与解码设独立的显存配额，预填侧在配额不足时排队而非抢占。</p>\n<p>代价上，按实际 patch 数重算预算需要在视觉编码前完成尺寸检查，增加一次元数据查询的延迟，但避免了预填中途失败的重试成本；预填/解码显存配额分离会降低批内并发度，吞吐下降换取 OOM 归零。具体例子：NVL72 单节点上多个副本共享显存池时，一个副本的预填峰值会挤压其他副本的解码空间，配额分离必须在副本级而非进程级实施，否则 OOM 只是从一个副本转移到另一个。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-43\">四十三 · 批抖动与路由不均：保留率作为调度维度</h3>\n<p>批抖动指同一批内请求的预填时长差异过大，导致批完成时间被最慢请求拖长，GPU 空转。ViTCoP 引入了一个新的抖动源：<strong>保留率异质性</strong>。指令明确的请求保留率低、预填快；长文档或模糊指令的请求保留率高、预填慢。若调度器按到达顺序组批，快慢请求混批，快请求完成后其 KV 占着显存等待慢请求，批的有效吞吐被拉低。诊断信号是批内预填时长的基尼系数与批完成时间的尾部比值，两者同时升高即判定为保留率异质性驱动的抖动。</p>\n<p>路由不均则是另一层：多副本部署下，若前端按轮询分发请求而不感知保留率，某些副本持续接收高保留率请求，其队列深度与 TTFT 系统性偏高，而低保留率副本空闲。解法是把保留率预估作为路由权重——在 tokenize 阶段用图像 patch 数与指令长度做一个轻量预估，把高保留率请求优先路由到队列浅的副本，或按预估保留率做一致性哈希使同类请求聚集。代价是预估本身有误差，误判会导致副本间负载再次失衡，因此预估器需要在线校准：用实际保留率回填预估误差，按滑动窗口更新路由权重。</p>\n<p>具体例子：一个混合负载集群中，OCR 类请求保留率高、通用问答保留率低，若不做路由感知，OCR 请求会在某个副本上堆积形成尾延迟尖刺，而其他副本的 GPU 利用率不足。把保留率预估接入路由后，OCR 请求被分散到多个副本并各自组批，批内时长方差下降，尾延迟尖刺被削平。代价是路由层增加一次预估计算与状态查询，前端延迟增加，需把预估结果缓存在请求上下文里避免重复计算。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-44\">四十四 · 尾延迟尖刺的归因树</h3>\n<p>尾延迟尖刺在 ViTCoP 部署中是复合现象，必须用归因树而非单一指标定位。第一层区分尖刺发生在预填还是解码：预填尖刺表现为 TTFT 的 p99 抬升而 TPOT 平稳，解码尖刺则相反。第二层在预填尖刺内区分是打分慢、合并慢还是 LLM 预填慢——打分与合并是逐 token 的轻量算子，其耗时随 $N_{\\text{vis}}$ 线性增长，LLM 预填耗时随 $N_{\\text{vis}}'$ 与 $N_{\\text{txt}}$ 增长，三者的耗时比例在正常请求上稳定，比例偏移即指向具体阶段。第三层区分是单请求慢还是排队慢：单请求慢表现为该请求的 GPU 时间片长，排队慢表现为请求在队列中等待而 GPU 时间片正常。</p>\n<p>公式上，预填总时延可拆为打分合并段与 LLM 预填段，前者与 $N_{\\text{vis}}$ 成正比，后者按前文公式随 $N_{\\text{vis}}'$ 与 $N_{\\text{txt}}$ 变化。诊断时采集两段的实际耗时并与理论比例比对：若打分合并段占比异常升高，说明视觉 token 数超出预期或打分算子退化为非向量化路径；若 LLM 预填段占比异常升高而保留率正常，说明文本侧长度超预期或批内存在长文本请求拖累。</p>\n<p>代价上，分段计时需要在算子边界插入事件记录，在高频请求下事件记录本身成为开销，应只在采样请求上开启全量计时，其余请求只记录段边界的时间戳差值。具体例子：尾延迟尖刺伴随批内请求数骤降，通常是某个长预填请求占满 SM 导致后续请求无法组批，此时应检查该请求的保留率是否被误判为低——保留率误判使实际进入 LLM 的 token 远超预算，预填时间片被单个请求垄断。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-45\">四十五 · 监控指标与回滚策略</h3>\n<p>监控体系按三层组织：请求层、批层、集群层。请求层采集 TTFT、TPOT、保留率、分数 gap、输出重复率；批层采集批内预填时长方差、批完成时间 p99、KV 峰值、OOM 计数；集群层采集副本间 TTFT 分位数离散度、GPU 利用率方差、路由权重偏差。指标必须带请求画像标签（图像尺寸分桶、指令长度分桶、任务类型），否则聚合后的均值会掩盖分桶内的失效。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>主监控信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>打分区分度塌缩</td><td>分数 gap 分位数、保留率漂移</td><td>对该画像请求上调保留率或旁路压缩</td></tr><tr><td>合并信息坍缩</td><td>定位探针对齐率</td><td>对 OCR/定位类请求禁用合并，仅做筛选</td></tr><tr><td>预算漂移 OOM</td><td>图像尺寸高端分桶的 OOM 计数</td><td>按实际 patch 数重算预算并拒绝超限</td></tr><tr><td>KV 峰值叠加</td><td>批内解码请求数与 KV 峰值相关性</td><td>预填/解码显存配额分离</td></tr><tr><td>批抖动</td><td>批内预填时长基尼系数</td><td>按预估保留率分组批</td></tr><tr><td>路由不均</td><td>副本间 TTFT 离散度</td><td>启用保留率感知路由并校准权重</td></tr></tbody></table>\n<p>回滚策略的核心是<strong>分级降级而非整体关闭</strong>。ViTCoP 作为推理侧插件，训练无关的特性使其可以按请求画像粒度旁路：对判定为高风险的画像（长文档、模糊指令、OCR）直接走未压缩路径，其余请求继续压缩。降级开关必须能在请求级生效而非进程级，否则一次精度告警会导致整个副本失去加速收益。回滚的触发条件用滑动窗口统计而非单点阈值：分数 gap 的窗口分位数持续低于阈值、定位探针对齐率窗口下降超过容忍度、OOM 计数在窗口内非零，三者任一触发即对该画像降级。</p>\n<p>代价上，旁路压缩使该画像请求的 TTFT 回到未加速水平，吞吐下降；分级降级要求服务栈同时维护压缩与未压缩两条预填路径，显存预算需按最坏情况（未压缩）预留，这削弱了压缩带来的显存收益。工程判断是：显存预留按画像比例动态调整，高风险画像占比低的集群可以承受双路径并存，占比高的集群应优先修正打分器而非长期旁路。具体例子：OCR 请求占比高的文档处理服务，长期旁路压缩等于放弃 ViTCoP 的主要收益，正确做法是对 OCR 请求保留筛选但禁用合并，用筛选削减部分冗余 token 同时保住空间精度。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-46\">四十六 · 诊断工具链与工程判断</h3>\n<p>诊断工具链的最小闭环是：请求级 trace 携带三层信号、批快照在 OOM 与尖刺时刻自动落盘、画像分桶的指标看板支持按分位数下钻。工具链的关键设计是<strong>信号与决策解耦</strong>：采集层只记录事实，判定层用可配置规则做归因，执行层按归因结果触发降级或路由调整。三层分离使得规则可以在不重启服务的情况下更新，避免诊断逻辑变更引发新的抖动。</p>\n<p>工程判断落在三个取舍上。其一，监控开销与诊断精度的取舍：全量分段计时不可承受，采样计时加段边界时间戳是可行折中，但采样率过低会漏掉稀疏的尾延迟尖刺，采样应偏向高风险画像而非均匀分布。其二，压缩收益与精度保障的取舍：保留率上调直接损失 TTFT 收益，但对模糊指令画像是必要的，收益损失应按画像核算而非全局核算。其三，回滚速度与回滚范围的取舍：请求级降级响应快但双路径并存增加显存压力，进程级回滚释放显存但牺牲全部加速收益，选择取决于高风险画像的流量占比与显存余量。</p>\n<p>最后落在具体机制上：ViTCoP 的失败模式全部源于打分链路对文本指令的依赖，因此诊断的第一动作永远是检查 $\\mathbf{e}_t$ 与 $\\mathbf{v}_j$ 的分数分布，而非先怀疑硬件或调度。分数分布的 gap 是整套监控体系里信息量最高的单指标——它同时预示精度失效、保留率漂移与批抖动，把 gap 的分位数作为一级告警信号，其余指标作为二级归因信号，是这套系统在工程上最省成本的监控结构。</p>\n<h3 id=\"alg-vitcop-vlm-prefill-sec-47\">四十七 · 对照维度：先看“压缩发生在哪一层”</h3>\n<p>把 ViTCoP 放回同族算法的坐标系里，最有效的第一刀不是比精度，而是比“压缩动作发生在数据流的哪一层”。ViTCoP 的压缩点被严格钉在视觉编码器输出与 LLM 预填之间：ViT 已经吐出完整视觉 token 序列，此时用文本指令嵌入做一次跨模态打分，选出 top-$k$ 保留、其余按空间邻接合并为摘要 token，然后才拼进 LLM 预填。这意味着它的压缩是<strong>一次性、前置于 LLM、且不可回退</strong>的——进入 LLM 的视觉 token 集合在预填开始前就已定型。</p>\n<p>同族的 DUET-VLM 则把压缩拆成两段，第二段发生在 LLM 浅层内部，用注意力显著性做二次筛选；逐层视觉 token 压缩把削减动作分散到 LLM 的多个层，每层按自身注意力分布再裁一次；预语言模型视觉剪枝则把动作提前到 ViT 内部或 ViT 输出之前，连完整视觉 token 序列都不一定生成。这三类的共同点是“压缩点不同”，而压缩点直接决定了三件事：能否复用已被裁掉的 token 的信息、压缩决策能利用多少文本侧上下文、以及 KV cache 的分配时机。</p>\n<p>ViTCoP 的取舍很清楚：压缩点最靠前，所以它对预填 FLOPs 与 KV 写入量的削减最直接——KV cache 只对保留 token 分配，解码阶段复用，被合并掉的 token 根本不占 KV 预算。代价是决策时只握有文本指令嵌入与视觉 token 表示这一对静态信号，没有 LLM 浅层注意力这个更强的显著性来源。用公式说，ViTCoP 的保留判据是 $$s_j = \\cos(\\mathbf{e}_t, \\mathbf{v}_j),\\quad \\mathcal{K} = \\mathrm{TopK}(\\{s_j\\}, k)$$，打分函数里不出现任何 LLM 内部状态；而 DUET-VLM 的第二段判据必然含注意力权重，逐层压缩的判据则逐层变化。这个差别在指令明确时几乎无害，在指令模糊时就是精度缺口的来源。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-48\">四十八 · 决策表：五类候选的适用条件</h3>\n<p>下表把同族算法按“压缩点 / 决策信号 / 削减对象 / 精度风险面 / 集成成本”五个维度并列。表内不写具体加速倍数，因为各算法的收益强依赖保留率、图像分辨率与批形态，定性比较才是可迁移的判断依据。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>算法</th><th>压缩点</th><th>决策信号</th><th>主要削减对象</th><th>精度风险面</th><th>集成成本</th></tr>\n</thead>\n<tbody>\n<tr><td>ViTCoP</td><td>ViT 输出与 LLM 预填之间，一次性</td><td>文本指令嵌入 × 视觉 token 的余弦相关性</td><td>预填 FLOPs、KV 写入量</td><td>细粒度空间信息（OCR/定位）、指令模糊</td><td>低，训练无关插件</td></tr>\n<tr><td>DUET-VLM</td><td>两段：前置 + LLM 浅层注意力</td><td>相关性 + 浅层注意力显著性</td><td>预填 FLOPs、浅层计算</td><td>浅层注意力本身失真时的误裁</td><td>中，需接入 LLM 浅层</td></tr>\n<tr><td>逐层视觉 token 压缩</td><td>LLM 每层内部</td><td>逐层注意力分布</td><td>逐层计算量、KV 增长</td><td>层间裁剪误差累积</td><td>中高，需改模型前向</td></tr>\n<tr><td>预语言模型视觉剪枝</td><td>ViT 内部或输出前</td><td>视觉侧显著性（无文本）</td><td>ViT 编码算力</td><td>与指令无关的粗剪，可能剪掉指令相关区域</td><td>中，需改视觉塔</td></tr>\n<tr><td>近似误差引导压缩</td><td>随压缩算子而定</td><td>重建/近似误差界</td><td>视具体算子</td><td>误差界与实际任务精度不总对齐</td><td>中，需误差估计回路</td></tr>\n</tbody>\n</table>\n<p>读表的方式是“先定约束，再选行”。若服务栈不允许改模型前向、只允许在请求路径上加插件，那么逐层压缩与预语言模型剪枝直接出局，候选只剩 ViTCoP、DUET-VLM 与近似误差引导压缩；若 SLO 的瓶颈明确落在 TTFT 而非解码吞吐，则削减对象必须命中预填 FLOPs 与 KV 写入量，ViTCoP 与 DUET-VLM 同时命中，但后者多付一份接入 LLM 浅层的工程成本。反过来，若瓶颈在 ViT 编码本身（高分辨率、大 patch 数），ViTCoP 帮不上忙——它在 ViT 之后才动手，此时应转向预语言模型视觉剪枝。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-49\">四十九 · 用预填代价公式做取舍</h3>\n<p>把候选算法代进预填代价式，能看清“削减的是哪一项”，从而判断收益是否落在自己的瓶颈上：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>式中 $N_{\\text{vis}}'$ 是进入 LLM 的视觉 token 数。ViTCoP 直接压 $N_{\\text{vis}}'$，因此第一项（视觉侧投影与注意力的算力项）、第二项（视觉-文本交叉注意力的算力项）与第三项（KV 写入的带宽项）同时按保留率近似线性缩小——这是它 TTFT 随保留率近似线性下降的结构性原因，也是它相对“只削算力不削 KV”的方案的额外收益。逐层压缩则不同：它压的是层内计算量，$N_{\\text{vis}}'$ 在预填入口处并未减小，KV 分配仍按入口 token 数走，第三项几乎不动。预语言模型视觉剪枝压的是 ViT 侧算力，压根不出现在这个式子里，对 TTFT 的贡献只通过缩短 ViT 阶段体现。</p>\n<p>具体例子：一个图像加指令的预填请求，视觉 token 数远大于文本 token 数，$N_{\\text{vis}}'$ 主导两项算力项。若保留率取中低档，ViTCoP 让三项同步收缩，TTFT 的改善是“乘法式”的；若换成逐层压缩，预填入口的 $N_{\\text{vis}}'$ 不变，KV 带宽项成为硬底，TTFT 的下降会被这一项钳住。工程判断由此得出：<strong>当 KV 写入带宽而非纯算力是预填瓶颈时，压缩点必须前置到 LLM 入口之前</strong>，这正是 ViTCoP 相对层内压缩的结构性优势，也是它与跨阶段并行服务的分工线——后者改变阶段并行拓扑，不削减预填 FLOPs，两者可以叠加而不互斥。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-50\">五十 · 与量化类、投机类的正交关系</h3>\n<p>同族条目里还有多模态全静态量化与量化感知视觉剪枝，它们常被误当成 ViTCoP 的替代品。实际关系是正交的：量化改的是每个 token 的位宽与算子精度（NVFP4/FP8、tcgen05 路径上的吞吐），ViTCoP 改的是 token 的数量。前者压低单位 token 的成本，后者压低 token 的个数，二者在预填代价式里作用于不同因子——量化影响 $\\text{FLOPS}_{\\text{eff}}$ 与 $\\text{BW}$ 的有效值，ViTCoP 影响 $N_{\\text{vis}}'$。因此“先量化还是先压缩”不是二选一，而是看边际收益：当 $N_{\\text{vis}}'$ 已经很大且冗余明显时，压 token 数的收益通常大于再压位宽；当 token 数已被压到预算内、算力仍紧，才轮到量化收尾。量化感知视觉剪枝则是两者的耦合形态，把位宽与保留率放进同一个决策回路，代价是标定与调参复杂度上升。</p>\n<p>与多模态自适应投机解码的关系同理：投机解码优化的是解码阶段的接受率与步数，ViTCoP 优化的是预填阶段的入口 token 数，两者作用于不同阶段，可同时启用。但要注意一个耦合点——ViTCoP 的保留率设置过低时，KV cache 虽减小，解码阶段上下文不足会导致重复生成或答非所问，此时投机解码的接受率也会被拖低，因为草稿模型与目标模型共享同一份贫化上下文。这说明保留率不是孤立旋钮，它同时是预填加速比与解码质量的共同参数。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-51\">五十一 · 适用条件清单与不适用信号</h3>\n<p>把选择收敛成可执行的判断清单，按优先级排列：</p>\n<ul>\n<li><strong>指令明确、查询式请求</strong>：文本指令嵌入与视觉区域的相关性区分度高，top-$k$ 保留能稳定命中关键区域，ViTCoP 是首选，且因训练无关可作为推理侧插件低风险接入。</li>\n<li><strong>服务栈不可改模型前向</strong>：排除逐层压缩与预语言模型剪枝，ViTCoP 与近似误差引导压缩二选一；后者需要误差估计回路，集成成本更高。</li>\n<li><strong>瓶颈在预填 KV 写入带宽</strong>：必须选压缩点前置于 LLM 入口的方案，ViTCoP 命中；层内压缩不解决这一项。</li>\n<li><strong>瓶颈在 ViT 编码算力</strong>：ViTCoP 不适用，转向预语言模型视觉剪枝。</li>\n<li><strong>需要文本侧显著性参与决策</strong>：DUET-VLM 的两段式更稳，代价是接入 LLM 浅层。</li>\n<li><strong>OCR、定位、细粒度空间依赖任务</strong>：不适用。空间邻接合并的摘要 token 丢失位置信息，精度下降明显，应改用不合并、只做保序裁剪或量化的方案。</li>\n<li><strong>长文档、指令模糊场景</strong>：相关性打分区分度低，top-$k$ 保留率无法自适应，关键视觉 token 被误删的风险高；此时应引入自适应保留率或退回 DUET-VLM 的浅层注意力二次校正。</li>\n</ul>\n<p>不适用信号同样要能识别：当监控显示预填阶段 KV 分配量已接近预算上限而 TTFT 仍高，说明瓶颈不在 token 数而在带宽或调度，压缩收益有限；当解码侧出现重复生成或答非所问且保留率处于低位，说明压缩已越过质量悬崖，应上调保留率而非继续压。这两条信号把“算法选型”与“参数整定”分开，避免把保留率问题误诊为算法不匹配。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-52\">五十二 · 组合顺序：把同族算法排成流水线</h3>\n<p>同族算法并非互斥，工程上更常见的是排成一条压缩流水线，关键是顺序。合理的顺序遵循“先粗后细、先无损后有损、先便宜后昂贵”：预语言模型视觉剪枝在 ViT 侧做与指令无关的粗剪，成本最低但风险最高（可能剪掉指令相关区域），只适合在分辨率极高、冗余极明显时作为前置；ViTCoP 在 LLM 入口做指令相关的一次性筛选与合并，是主压缩级；DUET-VLM 的浅层注意力校正若启用，则作为后置精修，只对 ViTCoP 保留集做二次裁剪，避免两段都做全量打分造成重复开销。量化放在最后，对已压缩的 token 集合做位宽收敛。</p>\n<p>顺序颠倒会带来具体代价：若先量化再 ViTCoP，相关性打分在低精度表示上进行，$\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 的区分度被数值噪声侵蚀，top-$k$ 选择失准；若先 DUET-VLM 浅层校正再 ViTCoP，浅层注意力已在全量 token 上付出计算，ViTCoP 的前置削减失去意义，预填 FLOPs 的节省被抵消。因此流水线的判据是：<strong>任何以“减少进入下一级的 token 数”为目标的级，必须排在以“提升单位 token 质量”为目标的级之前</strong>。ViTCoP 在这条流水线里的位置是主压缩级——它既利用文本指令这一廉价而有效的信号，又把削减效果同时落在算力项与 KV 带宽项上，是预填加速的主力，而其余同族算法围绕它做前置粗剪、后置精修与位宽收尾。</p>\n\n<h3 id=\"alg-vitcop-vlm-prefill-sec-53\">五十三 · 选型边界：什么时候该用 ViTCoP，什么时候该换别的路</h3>\n<p>把 ViTCoP 放进同族算法的坐标系里，判据只有一条：压缩发生在数据流的哪一段。ViTCoP 只在视觉编码器输出与 LLM 预填之间做一次性打分筛选，不进入 LLM 浅层做二次注意力显著性压缩——这正是它与 DUET-VLM 的分水岭。若任务需要模型自身在浅层注意力里重新评估视觉 token 的重要性（例如指令与图像内容存在多跳指代），一次性打分的信息量不够，应选跨阶段方案；若追求训练无关、低集成风险，ViTCoP 的插件形态更划算。它与跨阶段并行服务的差别则在于代价落在哪里：ViTCoP 削减的是预填 FLOPs 与 KV 写入量，而并行服务改变的是阶段拓扑，两者可以叠加但不可互相替代。</p>\n<p>保留率 $k/N_{\\text{vis}}$ 是唯一可调旋钮，其收益直接体现在预填时延公式的第一、二项上：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}\\approx \\frac{4\\,N_{\\text{vis}}' d^2 + 2\\,N_{\\text{vis}}' N_{\\text{txt}} d}{\\text{FLOPS}_{\\text{eff}}}+\\frac{2\\,N_{\\text{vis}}' d\\,B_{\\text{kv}}}{\\text{BW}}$$</div>\n<p>其中 $N_{\\text{vis}}'$ 为压缩后进入 LLM 的视觉 token 数。TTFT 随保留率近似线性下降，但这条线性只在打分区分度足够时成立。指令明确、单图问答类请求，分数分布呈双峰，top-$k$ 截断干净，收益接近理论上限；指令模糊或长文档场景，$s_j=\\cos(\\mathbf{e}_t,\\mathbf{v}_j)$ 的分布被压平，截断边界落在大量同分 token 上，误删关键 patch 的概率上升，此时应提高保留率或退回不压缩路径。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>推荐路径</th><th>主要代价</th></tr></thead><tbody><tr><td>指令明确的单图查询</td><td>ViTCoP，低保留率</td><td>打分开销，可忽略</td></tr><tr><td>OCR / 定位 / 细粒度计数</td><td>不压缩或仅合并冗余 patch</td><td>TTFT 无改善</td></tr><tr><td>长文档多图、指令含糊</td><td>ViTCoP 高保留率 + 跨阶段方案</td><td>KV 写入量回升，收益收窄</td></tr><tr><td>需浅层注意力重估</td><td>DUET-VLM 类方案</td><td>侵入 LLM 前向，集成成本高</td></tr></tbody></table>\n<p>失效条件要盯住解码侧而非只看预填。保留率压得过低时，KV cache 确实缩小、预填变快，但解码阶段可用上下文不足，模型出现重复生成或答非所问——这是压缩收益被下游质量反噬的典型路径。工程判断上，应把保留率与任务类型绑定成静态档位而非全局单值：查询类走激进档，文档理解类走保守档，OCR/定位类直接旁路 ViTCoP。空间邻接合并产生的摘要 token 丢失细粒度位置信息，是这条路径不可修复的结构性代价，任何调参都无法在定位任务上把它补回来。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 多模态Agent低延迟服务</td></tr><tr><td>解决什么</td><td>VLM 预填阶段视觉 token 数量远超文本 token，视觉编码与 LLM 预填的算力与带宽被大量冗余视觉 tok…</td></tr><tr><td>一句话机制</td><td>在视觉编码器输出与 LLM 预填之间引入视觉-文本语义协同打分，按文本指令相关性对视觉 token 做一次性筛选与合并…</td></tr><tr><td>代价与失效</td><td>相关性打分依赖文本指令，指令模糊或长文档场景下保留率难以自适应；合并摘要 token 会损失细粒度空间信息，OCR/定位类任务精度下降</td></tr><tr><td>后继</td><td>多模态分页KV与视觉块共享</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vitcop-vlm-prefill · 共 8 个片段</p>\n";break;}}})();
